div.script:
//
&lt;![CDATA[
$(document).ready(function() {
    function displayNum() {
        let dataLocal = JSON.parse(localStorage.getItem(&#39;bookmark&#39;) || &#39;[]&#39;);
        $(&#39;.numshow&#39;).html(dataLocal.length);
    }
    displayNum();

    const limitBookmark = 100;
    const bookmark = (function() {
        let list = JSON.parse(localStorage.getItem(&#39;bookmark&#39;) || &#39;[]&#39;);

        // Define the structure for each bookmarked item
        function Item(id, name, status, type, link, img) {
            this.id = id;
            this.name = name;
            this.status = status;
            this.type = type;
            this.link = link;
            this.img = img;
        }

        // Save bookmarks to local storage
        function setBookmark() {
            localStorage.setItem(&#39;bookmark&#39;, JSON.stringify(list));
        }

        // Object containing bookmark functions
        const obj = {};

        // Function to add an item to bookmarks
        obj.addItemTobookmark = function(id, name, status, type, link, img) {
            if (list.length &lt; limitBookmark &amp;&amp; !list.some(item =&gt; item.id === id)) {
                list.push(new Item(id, name, status, type, link, img));
                setBookmark();
            }
        };

        // Function to remove an item from bookmarks
        obj.removeThisItem = function(id) {
            list = list.filter(item =&gt; item.id !== id);
            setBookmark();
        };

        return obj;
    })();

    // Setup the bookmark button for each item
    $(&#39;.bookmark&#39;).each(function() {
        const dataId = $(this).data(&#39;id&#39;);
        const getData = JSON.parse(localStorage.getItem(&#39;bookmark&#39;) || &#39;[]&#39;);

        // Set the initial state of the bookmark button
        if (getData.some(item =&gt; item.id == dataId)) {
            $(this).text(&#39;Bookmarked&#39;).addClass(&#39;bookmarked&#39;);
        } else {
            $(this).text(&#39;Bookmark&#39;);
        }

        // Click event for the bookmark button
        $(this).click(function() {
            const id = $(this).data(&#39;id&#39;);
            const name = $(&#39;.info .title&#39;).text().trim();
            const link = window.location.href;
            const img = $(&#39;#info .thumb div img&#39;).attr(&#39;src&#39;);
            const status = $(&#39;.meta .status span&#39;).text().trim();
            const type = $(&#39;.meta .type span a&#39;).text().trim();

            if (!$(this).hasClass(&#39;bookmarked&#39;)) {
                bookmark.addItemTobookmark(id, name, status, type, link, img);
                $(this).text(&#39;Bookmarked&#39;).addClass(&#39;bookmarked&#39;);
            } else {
                bookmark.removeThisItem(id);
                $(this).text(&#39;Bookmark&#39;).removeClass(&#39;bookmarked&#39;);
            }
            displayNum();
        });
    });
});
]]&gt;
