b:includable.script:
//
  (function() {
    /* ═══════════════════════════════════════════════════════
       Sports 803 – Post Reactions (Like / Dislike / Save)
       Fixed: v2.1 – 2025
       Bugs fixed:
         1. isPost ReferenceError (was not declared in this scope)
         2. Async handler ordering – persist/syncState now run
            BEFORE awaiting Firebase so UI always updates
         3. initRealtimeReactions wrapped in try/catch
         4. Full localStorage fallback when Firebase is unavailable
    ═══════════════════════════════════════════════════════ */

    /* ── 0. Constants & guards ── */
    var KEY_L = 'sports803_yt_likes';
    var KEY_D = 'sports803_yt_dislikes';
    var KEY_S = 'sports803_saved';
    var url   = window.location.href;

    /* FIX 1: Define isPost in this scope */
    var isPost = /\/\d{4}\/\d{2}\//.test(window.location.pathname);

    /* FIX 2: Defensive guard – Firebase globals may not be ready */
    var hasFirebase = (typeof rtdb !== 'undefined' && rtdb !== null);
    var hasDeviceId = (typeof DEVICE_ID !== 'undefined');

    var postTitle = document.title.split(/\s*[|\u2013\-]\s*/)[0].trim();
    var postThumb = '';
    var og = document.querySelector('meta[property="og:image"]');
    if (og) postThumb = og.getAttribute('content');
    if (!postThumb) {
      var im = document.querySelector('.post-body img,article img');
      if (im) postThumb = im.src;
    }

    /* ── localStorage helpers ── */
    function load(k)       { try { return JSON.parse(localStorage.getItem(k)) || {}; } catch(e) { return {}; } }
    function persist(k, o) { try { localStorage.setItem(k, JSON.stringify(o)); } catch(e) {} }

    var likes    = load(KEY_L);
    var dislikes = load(KEY_D);
    var saved    = load(KEY_S);

    /* ── DOM refs ── */
    var btnL = document.getElementById('ytr-like');
    var btnD = document.getElementById('ytr-dislike');
    var btnS = document.getElementById('ytr-save');
    var cntL = document.getElementById('ytr-like-count');
    var cntD = document.getElementById('ytr-dislike-count');
    var cntS = document.getElementById('ytr-save-count');

    if (!btnL || !btnD || !btnS) {
      /* Reaction buttons not present, but still boot comments if on a post */
      if (isPost && hasFirebase) {
        /* postKey already computed above */
        initRealtimeComments();
      }
      return; /* skip reactions */
    }

    /* ── Firebase path key ── */
    var postKey = url
      .replace(/https?:\/\/[^/]+/, '')
      .replace(/[^a-z0-9]/gi, '_')
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '')
      .toLowerCase() || 'home';

    /* ── Sync visual state from localStorage ── */
    function syncState() {
      btnL.classList.toggle('ytr-active', !!likes[url]);
      btnD.classList.toggle('ytr-active', !!dislikes[url]);
      btnS.classList.toggle('ytr-active', !!saved[url]);
    }

    /* ── Pop animation ── */
    function pop(btn) {
      btn.classList.remove('ytr-pop');
      void btn.offsetWidth;
      btn.classList.add('ytr-pop');
      setTimeout(function() { btn.classList.remove('ytr-pop'); }, 320);
    }

    /* ── Firebase helpers (only called when hasFirebase is true) ── */
    function fbSet(path, val) {
      try { return rtdb.ref(path).set(val); } catch(e) { return Promise.reject(e); }
    }
    function fbRemove(path) {
      try { return rtdb.ref(path).remove(); } catch(e) { return Promise.reject(e); }
    }
    function fbTransaction(path, fn) {
      try { return rtdb.ref(path).transaction(fn); } catch(e) { return Promise.reject(e); }
    }

    /* ── Atomic reaction counter update ── */
    function updateReaction(type, delta) {
      if (!hasFirebase) return Promise.resolve();
      return fbTransaction('reactions/' + postKey, function(current) {
        current = current || { likes: 0, dislikes: 0 };
        if (type === 'likes') {
          current.likes = Math.max(0, (current.likes || 0) + delta);
        } else if (type === 'dislikes') {
          current.dislikes = Math.max(0, (current.dislikes || 0) + delta);
        }
        return current;
      }).then(function() {
        /* Also log user action */
        if (hasDeviceId) {
          var actionPath = 'user_actions/' + DEVICE_ID + '/' + postKey;
          fbSet(actionPath, delta > 0 ? type : null).catch(function() {});
        }
      });
    }

    /* FIX 3: Wrap realtime listener in try/catch so a Firebase error
       here does NOT prevent event listeners below from attaching */
    function initRealtimeReactions() {
      if (!hasFirebase) return;
      try {
        rtdb.ref('reactions/' + postKey).on('value', function(snapshot) {
          try {
            var data = snapshot.val() || { likes: 0, dislikes: 0 };
            if (cntL) cntL.textContent = data.likes    || 0;
            if (cntD) cntD.textContent = data.dislikes || 0;
            /* Update trending score in background */
            if (data.likes > 0) {
              fbSet('trending/' + postKey, {
                title: postTitle,
                url: url,
                thumb: postThumb,
                likes: data.likes,
                updatedAt: Date.now()
              }).catch(function() {});
            }
          } catch(innerErr) {
            console.warn('[S803] Reaction snapshot parse error:', innerErr);
          }
        });
      } catch(err) {
        console.warn('[S803] initRealtimeReactions failed:', err);
      }
    }
    initRealtimeReactions();

    /* ══════════════════════════════════════════════════════
       FIX 4: Optimistic updates — localStorage + UI update
       runs SYNCHRONOUSLY first.  Firebase syncs afterwards
       in the background and is wrapped in its own try/catch.
       This guarantees the button always responds visually.
    ══════════════════════════════════════════════════════ */

    /* ── Like button ── */
    btnL.addEventListener('click', function(e) {
      e.stopPropagation();
      var wasLiked  = !!likes[url];
      var wasDis    = !!dislikes[url];
      var postData  = { title: postTitle, url: url, thumbnail: postThumb,
                        timestamp: new Date().toISOString() };

      /* 1 – Update local state */
      if (wasLiked) {
        delete likes[url];
        if (cntL) cntL.textContent = Math.max(0, (parseInt(cntL.textContent) || 0) - 1);
      } else {
        if (wasDis) {
          delete dislikes[url];
          if (cntD) cntD.textContent = Math.max(0, (parseInt(cntD.textContent) || 0) - 1);
        }
        likes[url] = postData;
        pop(btnL);
        if (cntL) cntL.textContent = (parseInt(cntL.textContent) || 0) + 1;
      }
      persist(KEY_L, likes);
      persist(KEY_D, dislikes);
      syncState();
      if (window.renderSidebarLiked) window.renderSidebarLiked();

      /* 2 – Firebase sync in background */
      if (hasFirebase && hasDeviceId) {
        var likeRef = 'user_liked/' + DEVICE_ID + '/' + postKey;
        if (wasLiked) {
          updateReaction('likes', -1).catch(function() {});
          fbRemove(likeRef).catch(function() {});
        } else {
          updateReaction('likes',  1).catch(function() {});
          fbSet(likeRef, postData).catch(function() {});
          if (wasDis) {
            updateReaction('dislikes', -1).catch(function() {});
            fbRemove('user_liked/' + DEVICE_ID + '/' + postKey + '_dislike').catch(function() {});
          }
        }
      }
    });

    /* ── Dislike button ── */
    btnD.addEventListener('click', function(e) {
      e.stopPropagation();
      var wasDis  = !!dislikes[url];
      var wasLiked = !!likes[url];

      /* 1 – Update local state */
      if (wasDis) {
        delete dislikes[url];
        if (cntD) cntD.textContent = Math.max(0, (parseInt(cntD.textContent) || 0) - 1);
      } else {
        if (wasLiked) {
          delete likes[url];
          if (cntL) cntL.textContent = Math.max(0, (parseInt(cntL.textContent) || 0) - 1);
        }
        dislikes[url] = 1;
        pop(btnD);
        if (cntD) cntD.textContent = (parseInt(cntD.textContent) || 0) + 1;
      }
      persist(KEY_L, likes);
      persist(KEY_D, dislikes);
      syncState();
      if (window.renderSidebarLiked) window.renderSidebarLiked();

      /* 2 – Firebase sync in background */
      if (hasFirebase && hasDeviceId) {
        if (wasDis) {
          updateReaction('dislikes', -1).catch(function() {});
        } else {
          updateReaction('dislikes', 1).catch(function() {});
          if (wasLiked) {
            updateReaction('likes', -1).catch(function() {});
            fbRemove('user_liked/' + DEVICE_ID + '/' + postKey).catch(function() {});
          }
        }
      }
    });

    /* ── Save button ── */
    btnS.addEventListener('click', function(e) {
      e.stopPropagation();
      var wasSaved = !!saved[url];
      var postData = { title: postTitle, url: url, thumbnail: postThumb,
                       timestamp: new Date().toISOString() };

      /* 1 – Update local state */
      if (wasSaved) {
        delete saved[url];
        if (cntS) cntS.textContent = Math.max(0, (parseInt(cntS.textContent) || 1) - 1);
      } else {
        saved[url] = postData;
        pop(btnS);
        if (cntS) cntS.textContent = (parseInt(cntS.textContent) || 0) + 1;
      }
      persist(KEY_S, saved);
      syncState();
      if (window.renderSidebarSaved) window.renderSidebarSaved();

      /* 2 – Firebase sync in background */
      if (hasFirebase && hasDeviceId) {
        var saveRef = 'user_saved/' + DEVICE_ID + '/' + postKey;
        if (wasSaved) {
          fbRemove(saveRef).catch(function() {});
        } else {
          fbSet(saveRef, postData).catch(function() {});
        }
      }
    });

    /* ── Realtime Comments ── */
    function initRealtimeComments() {
      if (!hasFirebase) return;
      var feed  = document.getElementById('s803-comments-feed');
      var input = document.getElementById('s803-comment-field');
      var btn   = document.getElementById('s803-submit-comment');
      if (!feed || !btn) return;

      /* ── Move comments container immediately after .post-body-container ── */
      var commentsBox = document.querySelector('.s803-comments-container');
      var postBody    = document.querySelector('.post-body-container');
      if (commentsBox && postBody && commentsBox.parentNode !== postBody.parentNode) {
        postBody.parentNode.insertBefore(commentsBox, postBody.nextSibling);
      }

      /* ── Set avatar initial letter from device / user ID ── */
      var avatarEl = document.getElementById('s803-user-avatar');
      if (avatarEl) {
        var initLetter = hasDeviceId ? DEVICE_ID.substr(-1).toUpperCase() : 'U';
        avatarEl.textContent = initLetter;
      }

      try {
        rtdb.ref('comments/' + postKey)
          .orderByChild('timestamp')
          .limitToLast(50)
          .on('value', function(snapshot) {
            if (!snapshot.exists()) {
              feed.innerHTML = '<div style="text-align:center;padding:20px;color:#777;">No comments yet. Be the first!</div>';
              return;
            }
            var data = [];
            snapshot.forEach(function(child) {
              data.push(Object.assign({ _id: child.key }, child.val()));
            });
            data.reverse();
            feed.innerHTML = '';
            data.forEach(function(c) {
              var date     = c.timestamp ? new Date(c.timestamp).toLocaleDateString() : 'Just now';
              var initials = c.author ? c.author.charAt(0).toUpperCase() : 'U';
              var item     = document.createElement('div');
              item.className = 's803-comment-item';
              item.innerHTML =
                '<div class="s803-user-avatar">' + initials + '</div>' +
                '<div class="s803-comment-content">' +
                  '<div class="s803-comment-author">' + (c.author || 'User') +
                    ' <span class="s803-comment-time">' + date + '</span></div>' +
                  '<div class="s803-comment-text">' + (c.text || '') + '</div>' +
                  '<div class="s803-comment-actions">' +
                    '<button class="s803-action-btn" onclick="window.s803LikeComment(\'' + c._id + '\')">' +
                      '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M1 21h4V9H1v12zm22-11c0-1.1-.9-2-2-2h-6.31l.95-4.57.03-.32c0-.41-.17-.79-.44-1.06L14.17 1 7.59 7.59C7.22 7.95 7 8.45 7 9v10c0 1.1.9 2 2 2h9c.75 0 1.41-.41 1.75-1.03l3.12-7.29c.08-.19.13-.4.13-.61v-2z"/></svg>' +
                      '<span id="s803-cl-' + c._id + '">' + (c.likes || 0) + '</span>' +
                    '</button>' +
                  '</div>' +
                '</div>';
              feed.appendChild(item);
            });
          });
      } catch(err) {
        console.warn('[S803] Comment listener error:', err);
      }

      /* Prevent duplicate submit listeners */
      if (btn._s803commentBound) return;
      btn._s803commentBound = true;

      btn.addEventListener('click', function() {
        var text = input ? input.value.trim() : '';
        if (!text) return;
        btn.disabled = true;
        var authorTag = hasDeviceId ? 'User_' + DEVICE_ID.substr(-4) : 'User';
        fbSet('comments/' + postKey + '/' + Date.now(), {
          author: authorTag,
          text: text,
          deviceId: hasDeviceId ? DEVICE_ID : 'anon',
          likes: 0,
          timestamp: Date.now()
        }).then(function() {
          input.value = '';
        }).catch(function(err) {
          console.warn('[S803] Comment post failed:', err);
        }).then(function() {
          btn.disabled = false;
        });
      });
    }
    initRealtimeComments();

    window.s803LikeComment = function(commentId) {
      if (!hasFirebase) return;
      fbTransaction('comments/' + postKey + '/' + commentId + '/likes',
        function(cur) { return (cur || 0) + 1; }
      ).then(function(result) {
        /* Update like count span immediately without waiting for re-render */
        var span = document.getElementById('s803-cl-' + commentId);
        if (span && result && result.snapshot) span.textContent = result.snapshot.val() || '';
      }).catch(function() {});
    };
    /* Back-compat alias */
    window.likeComment = window.s803LikeComment;

    /* FIX 5: addToHistory uses local isPost (declared at top of IIFE) */
    function addToHistory() {
      if (!isPost) return;                          /* safe – isPost defined above */
      try {
        var history = JSON.parse(localStorage.getItem('sports803_history') || '[]');
        history = history.filter(function(p) { return p.url !== url; });
        var entry = { title: postTitle, url: url, thumb: postThumb, ts: Date.now() };
        history.unshift(entry);
        localStorage.setItem('sports803_history', JSON.stringify(history.slice(0, 20)));
        if (hasFirebase && hasDeviceId) {
          fbSet('user_history/' + DEVICE_ID + '/' + postKey, entry).catch(function() {});
        }
      } catch(err) {
        console.warn('[S803] addToHistory error:', err);
      }
    }
    addToHistory();

    /* ── Admin Live TV Panel ── */
    function initAdminPanel() {
      var isAdmin = new URLSearchParams(window.location.search).get('admin') === 'true';
      if (!isAdmin) return;
      var panel = document.createElement('div');
      panel.id = 's803-admin-panel';
      panel.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:9999;background:#1a1a1a;border:1px solid #3ea6ff;border-radius:12px;padding:15px;width:300px;box-shadow:0 10px 30px rgba(0,0,0,0.5)';
      panel.innerHTML =
        '<h4 style="margin:0 0 10px;color:#3ea6ff;">Admin Live TV Panel</h4>' +
        '<input id="adm-ch-name" placeholder="Channel Name" style="width:100%;background:#222;border:1px solid #333;color:#fff;padding:8px;border-radius:4px;margin-bottom:8px">' +
        '<input id="adm-ch-url" placeholder="Stream URL" style="width:100%;background:#222;border:1px solid #333;color:#fff;padding:8px;border-radius:4px;margin-bottom:8px">' +
        '<button id="adm-add-ch" style="width:100%;background:#3ea6ff;color:#000;border:none;padding:10px;border-radius:4px;font-weight:700;cursor:pointer">Add Channel</button>' +
        '<div id="adm-status" style="font-size:11px;margin-top:8px;color:#777">Only visible with ?admin=true</div>';
      document.body.appendChild(panel);
      document.getElementById('adm-add-ch').addEventListener('click', function() {
        var name   = document.getElementById('adm-ch-name').value;
        var stream = document.getElementById('adm-ch-url').value;
        if (!name || !stream) { alert('Fill all fields'); return; }
        if (!hasFirebase) { alert('Firebase not available'); return; }
        fbSet('livetv/channels/' + Date.now(), { name: name, url: stream, active: true, createdAt: Date.now() })
          .then(function() {
            alert('Channel added!');
            document.getElementById('adm-ch-name').value = '';
            document.getElementById('adm-ch-url').value  = '';
          })
          .catch(function(err) { alert('Error: ' + err.message); });
      });
    }
    initAdminPanel();

    syncState();
  })();
//

//
        var disqus_shortname = &quot;temabanua&quot;;
        var disqus_blogger_current_url = &quot;<data:post.url.canonical/>&quot;;
        if (!disqus_blogger_current_url.length) {
          disqus_blogger_current_url = &quot;<data:post.url.canonical/>&quot;;
        }
        var disqus_blogger_homepage_url = &quot;<data:blog.canonicalHomepageUrl/>&quot;;
        var disqus_blogger_canonical_homepage_url = &quot;<data:blog.canonicalHomepageUrl/>&quot;;

//

body.script:
//
window.S803_CFG = {};
(function(){
  var FB = 'https://sports-803-1b806-default-rtdb.firebaseio.com/s803config.json';
  try {
    var x = new XMLHttpRequest();
    x.open('GET', FB, false);
    x.send(null);
    if(x.status === 200){
      var d = JSON.parse(x.responseText);
      if(d && typeof d === 'object' && !d.error) window.S803_CFG = d;
    }
  } catch(e){ window.S803_CFG = {}; }
})();
//

//
(function () {
  'use strict';

  /* ══════════════════════════════
     ⚙️  SETTINGS — reads from Control Panel (Firebase) with hardcoded fallbacks
  ══════════════════════════════ */
  var _c = window.S803_CFG || {};

  var VIP_PIN    = _c.VIP_PIN    || '8033';
  var VIP_LABEL  = _c.VIP_LABEL  || 'app-vip';
  var LIVE_LABEL = _c.LIVE_LABEL || 'Live TV';
  var SITE_URL   = _c.SITE_URL   || 'https://sports803livestream.blogspot.com';
  var APP_LINK   = _c.APP_LINK   || '';
  var APP_NAME   = _c.app_name   || 'Sports 803';
  var APP_TAG    = _c.app_tagline|| 'Free Live Sports';

  /* — DEVICE — */
  var SA        = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
  var ua        = navigator.userAgent;
  var iOS       = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
  var isAndroid = /Android/i.test(ua);
  var isDesktop = !isAndroid && !iOS;

  function $id(id){ return document.getElementById(id); }
  function qs(s){   return document.querySelector(s); }
  function qsa(s){  return document.querySelectorAll(s); }

  /* ══════════════════════════════════════════════════════
     ✅ APPLY CONTROL PANEL CONFIG
  ══════════════════════════════════════════════════════ */
  (function applyControlPanelConfig(){
    var ACCENT_MAP = {
      default:'#e03030', blue:'#3b9eff', green:'#26c96a', gold:'#f5c842', purple:'#a855f7'
    };

    var accentKey = _c.accent_color || 'default';
    var accentHex = ACCENT_MAP[accentKey] || '#e03030';
    document.documentElement.style.setProperty('--s803-accent',  accentHex);
    document.documentElement.style.setProperty('--s803-accent2', accentHex.substring(0,7)+'80');
    document.documentElement.style.setProperty('--s803-glow',    accentHex.substring(0,7)+'55');
    if(accentKey !== 'default') document.body.setAttribute('data-theme', accentKey);

    var fHead = _c.font_head || 'Oswald';
    document.documentElement.style.setProperty('--s803-font-head', "'"+fHead+"', sans-serif");

    if(_c.ann_enabled && _c.ann_text){
      var annEl = document.createElement('div');
      var annColor = _c.ann_color || '#e03030';
      annEl.id = 's803-ann-bar';
      annEl.style.cssText = [
        'position:fixed','top:60px','left:0','right:0','z-index:9994',
        'background:'+annColor+'dd',
        'padding:7px 40px 7px 14px','font-family:var(--s803-font-body)',
        'font-size:12px','font-weight:700','color:#f0ede8','display:flex',
        'align-items:center','gap:8px','backdrop-filter:blur(10px)','-webkit-backdrop-filter:blur(10px)',
        'border-bottom:1px solid '+annColor+'55','box-shadow:0 2px 12px '+annColor+'33'
      ].join(';');
      var annLink = _c.ann_link ? ' href="'+_c.ann_link+'" target="_blank" rel="noopener"' : '';
      var annTag = _c.ann_link ? 'a' : 'span';
      annEl.innerHTML = '<'+annTag+annLink+' style="flex:1;text-decoration:none;color:inherit">'+_c.ann_text+'</'+annTag+'>'
        +'<button onclick="this.parentNode.style.display=\'none\'" style="position:absolute;right:8px;top:50%;transform:translateY(-50%);background:none;border:none;color:rgba(240,237,232,.5);font-size:16px;cursor:pointer;padding:0;line-height:1">✕</button>';
      document.addEventListener('DOMContentLoaded',function(){
        document.body.insertBefore(annEl, document.body.firstChild);
      });
    }

    if(_c.motd_enabled && _c.motd_home && _c.motd_away){
      document.addEventListener('DOMContentLoaded', function(){
        var motd = document.createElement('div');
        motd.id = 's803-motd';
        motd.style.cssText = 'margin:12px 0;border-radius:14px;overflow:hidden;font-family:var(--s803-font-body);'
          +'background:linear-gradient(135deg,rgba(224,48,48,0.12),rgba(0,0,0,0.6));border:1px solid rgba(224,48,48,0.22);';
        var url = _c.motd_url ? 'href="'+_c.motd_url+'"' : 'href="#"';
        motd.innerHTML = '<a '+url+' style="display:flex;flex-direction:column;align-items:center;padding:18px 14px;text-decoration:none;">'
          +'<div style="font-size:9px;font-weight:800;letter-spacing:.12em;color:var(--s803-accent);text-transform:uppercase;margin-bottom:10px">🏆 Match of the Day</div>'
          +'<div style="display:flex;align-items:center;gap:16px">'
          +'<div style="text-align:center"><div style="font-family:var(--s803-font-head);font-size:17px;font-weight:700;color:#f0ede8">'+_c.motd_home+'</div></div>'
          +'<div style="font-family:var(--s803-font-head);font-size:22px;font-weight:700;color:var(--s803-text2)">VS</div>'
          +'<div style="text-align:center"><div style="font-family:var(--s803-font-head);font-size:17px;font-weight:700;color:#f0ede8">'+_c.motd_away+'</div></div>'
          +'</div>'
          +(_c.motd_time?'<div style="font-size:11px;color:var(--s803-muted);margin-top:10px">⏰ '+_c.motd_time+'</div>':'')
          +'</a>';
        var tgt = document.querySelector('.blog-posts') || document.querySelector('#main-wrapper') || document.querySelector('.main-wrapper');
        if(tgt && tgt.firstChild) tgt.insertBefore(motd, tgt.firstChild);
      });
    }

    if(_c.featured_enabled && _c.featured_title && _c.featured_url){
      document.addEventListener('DOMContentLoaded', function(){
        var fp = document.createElement('div');
        fp.style.cssText = 'margin:10px 0;padding:12px 14px;background:rgba(59,158,255,0.07);border:1px solid rgba(59,158,255,0.22);border-left:3px solid #3b9eff;border-radius:12px;font-family:var(--s803-font-body);';
        fp.innerHTML = '<div style="font-size:9px;font-weight:800;color:#3b9eff;letter-spacing:.1em;text-transform:uppercase;margin-bottom:5px">📌 Featured Post</div>'
          +'<a href="'+_c.featured_url+'" style="font-size:13px;font-weight:700;color:#f0ede8;text-decoration:none;line-height:1.4">'+_c.featured_title+'</a>';
        var tgt = document.querySelector('.blog-posts') || document.querySelector('#main-wrapper') || document.querySelector('.main-wrapper');
        if(tgt && tgt.firstChild) tgt.insertBefore(fp, tgt.firstChild);
      });
    }

    if(_c.custom_css){
      var styleEl = document.createElement('style');
      styleEl.textContent = _c.custom_css;
      document.head.appendChild(styleEl);
    }

    document.addEventListener('DOMContentLoaded', function(){
      var splN = document.querySelector('.spl-name'); 
      if(splN && APP_NAME !== 'Sports 803'){
        var parts = APP_NAME.split(' ');
        splN.innerHTML = parts.length > 1
          ? parts.slice(0,-1).join(' ') + ' <span style="color:var(--s803-accent)">' + parts.slice(-1) + '</span>'
          : '<span style="color:var(--s803-accent)">' + APP_NAME + '</span>';
      }
      var splT = document.querySelector('.spl-tag'); if(splT && APP_TAG !== 'Free Live Sports') splT.textContent = APP_TAG;
      var splL = document.querySelector('.spl-logo'); if(splL && _c.splash_logo) splL.innerHTML = _c.splash_logo.replace(' ','<br/>');

      ['ip-logo','gate-logo'].forEach(function(id){
        var el = document.getElementById(id); if(!el||!_c.splash_logo)return;
        el.innerHTML = _c.splash_logo.replace(' ','<br/>');
      });

      var wlBtn = document.getElementById('s803-watch-live');
      if(wlBtn && _c.watch_live_label) wlBtn.childNodes[1].textContent = '📺 ' + _c.watch_live_label;

      if(_c.nav_items && _c.nav_items.length){
        var navEl = document.getElementById('s803-nav'); if(!navEl) return;
        var NAV_ID_MAP = {saved:'bkm',alerts:'bell',bkm:'bkm',bell:'bell',home:'home',live:'live',scores:'scores'};
        var SKIP_HREF  = ['#scores','#saved','#alerts','#bell','#bkm'];
        _c.nav_items.forEach(function(item){
          var rawId  = item.id || '';
          var navId  = NAV_ID_MAP[rawId] || rawId;
          var el     = navId ? document.getElementById('nav-' + navId) : null;
          if(!el) return;
          var iconEl  = el.querySelector('.nav-icon');
          var labelEl = el.querySelector('span:last-child, .nav-label');
          if(iconEl  && item.icon)  iconEl.textContent  = item.icon;
          if(labelEl && item.label) labelEl.textContent = item.label;
          if(item.href && SKIP_HREF.indexOf(item.href) === -1){
            if(el.tagName === 'A') el.href = item.href;
          }
        });
      }

      if(_c.footer_text){
        var fEl = document.querySelector('.blog-footer,.footer-outer,footer');
        if(fEl){var ft = document.createElement('div'); ft.style.cssText='text-align:center;padding:10px;font-size:11px;color:#555;font-family:var(--s803-font-body)'; ft.textContent=_c.footer_text; fEl.appendChild(ft);}
      }
    });

    if(_c.TICKER_LEAGUES && _c.TICKER_LEAGUES.length){
      window._s803TickerLeagues = _c.TICKER_LEAGUES;
    }

    if(_c.schedule_enabled && _c.fixtures && _c.fixtures.length){
      document.addEventListener('DOMContentLoaded', function(){
        var wrap = document.createElement('div');
        wrap.id = 's803-schedule';
        wrap.style.cssText = 'margin:12px 0;font-family:var(--s803-font-body)';
        var title = _c.schedule_title || 'This Week\'s Fixtures';
        var html = '<div style="font-size:10px;font-weight:800;color:var(--s803-accent);letter-spacing:.12em;text-transform:uppercase;margin-bottom:8px">📅 '+title+'</div>';
        html += '<div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:12px;overflow:hidden">';
        _c.fixtures.forEach(function(f, i){
          var dateStr='';
          if(f.date){try{dateStr=new Date(f.date+'T00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});}catch(e){dateStr=f.date;}}
          html += '<div style="padding:10px 14px;'+(i>0?'border-top:1px solid #151515':'')+';display:flex;align-items:center;gap:10px">'
            +'<div style="flex:1">'
            +'<div style="font-size:13px;font-weight:700;color:#f0ede8">'+f.home+' <span style="color:#333">vs</span> '+f.away+'</div>'
            +'<div style="font-size:10px;color:#555;margin-top:2px">'+(f.comp||'')+(dateStr?' · '+dateStr:'')+(f.time?' · '+f.time:'')+'</div>'
            +'</div>'
            +(f.url?'<a href="'+f.url+'" style="font-size:9px;font-weight:800;color:var(--s803-accent);background:rgba(224,48,48,.1);border:1px solid rgba(224,48,48,.2);border-radius:6px;padding:4px 10px;text-decoration:none;white-space:nowrap">▶ Watch</a>':'')
            +'</div>';
        });
        html += '</div>';
        wrap.innerHTML = html;
        var tgt = document.querySelector('.blog-posts') || document.querySelector('#main-wrapper') || document.querySelector('.main-wrapper');
        if(tgt){var ref = tgt.querySelector('#s803-motd') || tgt.firstChild; tgt.insertBefore(wrap, ref ? ref.nextSibling : tgt.firstChild);}
      });
    }

    if(_c.poll_enabled && _c.poll_question){
      document.addEventListener('DOMContentLoaded', function(){
        var FB_POLL = (window.S803_FB_URL||'https://sports-803-1b806-default-rtdb.firebaseio.com')+'/s803polls/active.json';
        var pollWrap = document.createElement('div');
        pollWrap.id = 's803-poll';
        pollWrap.style.cssText = 'margin:12px 0;font-family:var(--s803-font-body)';
        var ac = getComputedStyle(document.documentElement).getPropertyValue('--s803-accent').trim() || '#e03030';
        var opts = [_c.poll_a,_c.poll_b];
        if(_c.poll_c)opts.push(_c.poll_c);
        if(_c.poll_d)opts.push(_c.poll_d);
        var colors = ['#e03030','#3b9eff','#26c96a','#f5c842'];
        var voted = localStorage.getItem('s803_poll_voted') === _c.poll_question;
        function renderPoll(votes){
          var total = (votes.votes_a||0)+(votes.votes_b||0)+(votes.votes_c||0)+(votes.votes_d||0)||1;
          var keys = ['votes_a','votes_b','votes_c','votes_d'];
          var html = '<div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:12px;padding:14px">'
            +'<div style="font-size:10px;font-weight:800;color:'+ac+';letter-spacing:.1em;text-transform:uppercase;margin-bottom:8px">🗳️ Match Poll</div>'
            +'<div style="font-size:13px;font-weight:700;color:#f0ede8;margin-bottom:12px">'+_c.poll_question+'</div>';
          opts.forEach(function(o,i){
            var v=votes[keys[i]]||0, pct=Math.round(v/total*100);
            html += '<div style="margin-bottom:8px" data-opt="'+keys[i]+'">'
              +'<div style="display:flex;justify-content:space-between;font-size:11px;color:#b8b4b0;margin-bottom:4px"><span>'+o+'</span>'+(voted?'<span style="font-weight:800;color:'+colors[i]+'">'+pct+'%</span>':'')+'</div>'
              +'<div onclick="s803PollVote(\''+keys[i]+'\')" style="background:#1a1a1a;border-radius:20px;height:32px;cursor:'+(voted?'default':'pointer')+';overflow:hidden;position:relative">'
              +(voted?'<div style="background:'+colors[i]+';height:100%;width:'+pct+'%;display:flex;align-items:center;padding:0 10px;font-size:10px;font-weight:800;color:#fff;border-radius:20px;transition:width .5s">'+pct+'%</div>':'<div style="height:100%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#555">Tap to vote</div>')
              +'</div></div>';
          });
          html += '</div>';
          pollWrap.innerHTML = html;
        }
        window.s803PollVote = function(key){
          if(localStorage.getItem('s803_poll_voted')===_c.poll_question)return;
          var x=new XMLHttpRequest();x.open('GET',FB_POLL,true);
          x.onreadystatechange=function(){if(x.readyState!==4)return;var d={};try{d=JSON.parse(x.responseText)||{};}catch(e){}
            d[key]=(d[key]||0)+1;
            var x2=new XMLHttpRequest();x2.open('PUT',FB_POLL,true);x2.setRequestHeader('Content-Type','application/json');
            x2.onreadystatechange=function(){if(x2.readyState!==4)return;localStorage.setItem('s803_poll_voted',_c.poll_question);voted=true;try{renderPoll(JSON.parse(x2.responseText)||d);}catch(e){renderPoll(d);}};
            x2.send(JSON.stringify(d));};
          x.send(null);
        };
        var xv=new XMLHttpRequest();xv.open('GET',FB_POLL,true);
        xv.onreadystatechange=function(){if(xv.readyState!==4)return;var d={};try{d=JSON.parse(xv.responseText)||{};}catch(e){}renderPoll(d);};
        xv.send(null);
        var tgt = document.querySelector('.blog-posts')||document.querySelector('#main-wrapper')||document.querySelector('.main-wrapper');
        if(tgt) tgt.insertBefore(pollWrap, tgt.firstChild);
      });
    }

    if(_c.streams_enabled && _c.stream_sources && _c.stream_sources.length){
      document.addEventListener('DOMContentLoaded', function(){
        var vipUnlocked = localStorage.getItem('s803_excl_unlocked')==='1';
        if(_c.streams_vip_only && !vipUnlocked) return;
        var sw2 = document.createElement('div');
        sw2.id = 's803-streams';
        sw2.style.cssText = 'margin:12px 0;font-family:var(--s803-font-body)';
        var ac2 = '#e03030';
        var html = '<div style="background:#0d0d0d;border:1px solid rgba(224,48,48,.2);border-radius:12px;overflow:hidden">'
          +'<div style="background:rgba(224,48,48,.08);border-bottom:1px solid rgba(224,48,48,.15);padding:10px 14px;display:flex;align-items:center;gap:8px">'
          +'<div style="width:8px;height:8px;border-radius:50%;background:#e03030;animation:s803pulse 1s ease-in-out infinite;flex-shrink:0"></div>'
          +'<div style="font-size:12px;font-weight:800;color:#f0ede8;flex:1">'+(_c.stream_headline||'🔴 Live Stream Available')+'</div></div>'
          +'<div style="padding:10px 14px;display:flex;flex-wrap:wrap;gap:8px">';
        _c.stream_sources.forEach(function(s){
          html += '<a href="'+s.url+'" target="_blank" rel="noopener" style="display:flex;align-items:center;gap:6px;background:#151515;border:1px solid #252525;border-radius:8px;padding:8px 12px;text-decoration:none;flex:1;min-width:120px">'
            +'<span style="font-size:16px">'+s.icon+'</span>'
            +'<div><div style="font-size:11px;font-weight:700;color:#f0ede8">'+s.label+'</div><div style="font-size:9px;color:#555">'+s.quality+'</div></div></a>';
        });
        html += '</div>';
        if(_c.stream_backup){
          html += '<div style="border-top:1px solid #151515;padding:8px 14px;font-size:10px;color:#444;white-space:pre-line">'+_c.stream_backup+'</div>';
        }
        html += '</div>';
        sw2.innerHTML = html;
        var tgt = document.querySelector('.blog-posts')||document.querySelector('#main-wrapper')||document.querySelector('.main-wrapper');
        if(tgt) tgt.insertBefore(sw2, tgt.firstChild);
      });
    }

    if(_c.lang_enabled && _c.lang_active && _c.lang_active.length > 1){
      var LANG_STRINGS = {
        en:{watch_live:'Watch Live',scores:'Scores',saved:'Saved',alerts:'Alerts',live:'Live',home:'Home',vip_title:'VIP Exclusive',install_title:'Install App',search:'Search'},
        sw:{watch_live:'Tazama Sasa',scores:'Matokeo',saved:'Zilizohifadhiwa',alerts:'Tahadhari',live:'Moja Kwa Moja',home:'Nyumbani',vip_title:'VIP Pekee',install_title:'Pakua Programu',search:'Tafuta'},
        fr:{watch_live:'Regarder En Direct',scores:'Résultats',saved:'Sauvegardé',alerts:'Alertes',live:'En Direct',home:'Accueil',vip_title:'Contenu VIP',install_title:'Installer',search:'Rechercher'},
        ar:{watch_live:'شاهد الآن',scores:'النتائج',saved:'المحفوظة',alerts:'التنبيهات',live:'مباشر',home:'الرئيسية',vip_title:'محتوى VIP',install_title:'تحميل التطبيق',search:'بحث'},
        pt:{watch_live:'Assistir Ao Vivo',scores:'Resultados',saved:'Guardado',alerts:'Alertas',live:'Ao Vivo',home:'Início',vip_title:'Conteúdo VIP',install_title:'Instalar App',search:'Pesquisar'},
        es:{watch_live:'Ver En Vivo',scores:'Resultados',saved:'Guardado',alerts:'Alertas',live:'En Vivo',home:'Inicio',vip_title:'Contenido VIP',install_title:'Instalar App',search:'Buscar'}
      };
      function parseOverrides(raw){
        var out={};(raw||'').split('\n').forEach(function(line){var p=line.split('|');if(p.length>=2)out[p[0].trim()]=p.slice(1).join('|').trim();});return out;
      }
      var customOverrides = {sw:parseOverrides(_c.lang_sw_custom), fr:parseOverrides(_c.lang_fr_custom)};
      var currentLang = localStorage.getItem('s803_lang') || _c.lang_default || 'en';
      var langFlags = {en:'🇬🇧',sw:'🇰🇪',fr:'🇫🇷',ar:'🇸🇦',pt:'🇧🇷',es:'🇪🇸'};

      function applyLang(code){
        currentLang = code;
        localStorage.setItem('s803_lang', code);
        var strings = Object.assign({}, LANG_STRINGS[code]||LANG_STRINGS.en, customOverrides[code]||{});
        document.documentElement.dir = code==='ar' ? 'rtl' : 'ltr';
        document.querySelectorAll('.s803-nav .nav-item').forEach(function(item){
          var lbl = item.querySelector('span:last-child');
          if(!lbl)return;
          var txt = (lbl.textContent||'').toLowerCase().trim();
          if(txt==='home'||txt===LANG_STRINGS.en.home.toLowerCase()) lbl.textContent = strings.home;
          else if(txt==='live'||txt===LANG_STRINGS.en.live.toLowerCase()) lbl.textContent = strings.live;
          else if(txt==='scores'||txt===(LANG_STRINGS.en.scores||'').toLowerCase()) lbl.textContent = strings.scores;
          else if(txt==='saved'||txt===(LANG_STRINGS.en.saved||'').toLowerCase()) lbl.textContent = strings.saved;
          else if(txt==='alerts'||txt===(LANG_STRINGS.en.alerts||'').toLowerCase()) lbl.textContent = strings.alerts;
        });
        var wl = document.querySelector('#s803-watch-live .wl-text');
        if(!wl) wl = document.getElementById('s803-watch-live');
        if(wl) wl.textContent = '📺 ' + strings.watch_live;
        var lb = document.getElementById('s803-lang-btn');
        if(lb) lb.textContent = langFlags[code]||'🌍';
      }

      document.addEventListener('DOMContentLoaded', function(){
        var hdr = document.querySelector('.s803-header') || document.querySelector('#s803-header');
        if(hdr){
          var btn = document.createElement('button');
          btn.id = 's803-lang-btn';
          btn.textContent = langFlags[currentLang]||'🌍';
          btn.title = 'Change Language';
          btn.style.cssText = 'background:none;border:1px solid #252525;border-radius:8px;padding:5px 8px;font-size:14px;cursor:pointer;flex-shrink:0';
          btn.onclick = function(){
            var active = _c.lang_active||['en'];
            var idx = active.indexOf(currentLang);
            var next = active[(idx+1)%active.length];
            applyLang(next);
          };
          hdr.appendChild(btn);
        }
        applyLang(currentLang);
      });
