        var commWrap = document.createElement('div');
        commWrap.id = 's803-commentary';
        commWrap.style.cssText = 'margin:12px 0;font-family:var(--s803-font-body)';
        var status = _c.commentary_status||'pre';
        var statusColors = {pre:'#555',live:'#e03030',ht:'#f5c842',ft:'#3b9eff'};
        var statusLabels = {pre:'PRE-MATCH',live:'🔴 LIVE',ht:'HALF TIME',ft:'FULL TIME'};
        var sCol = statusColors[status]||'#555', sLbl = statusLabels[status]||'LIVE';
        var hS = _c.commentary_home_score||0, aS = _c.commentary_away_score||0;
        var parts = (_c.commentary_match||'').split(' vs ');
        var hN = parts[0]||'Home', aN = parts[1]||'Away';
        commWrap.innerHTML = '<div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:12px;overflow:hidden">'
          +'<div style="background:#080808;border-bottom:1px solid #151515;padding:10px 14px">'
