          +'<span style="font-size:9px;font-weight:800;background:'+sCol+';color:#fff;padding:2px 7px;border-radius:3px">'+sLbl+'</span>'
          +'<span style="font-size:11px;color:#555;flex:1">🎙️ Live Commentary</span></div>'
          +'<div style="display:flex;align-items:center;justify-content:center;gap:12px">'
          +'<div style="text-align:center"><div style="font-size:11px;font-weight:700;color:#b8b4b0;margin-bottom:4px">'+hN+'</div>'
          +'<div style="font-size:32px;font-weight:800;color:#f0ede8;font-family:var(--s803-font-head)">'+hS+'</div></div>'
          +'<div style="font-size:20px;color:#333;font-weight:300">—</div>'
          +'<div style="text-align:center"><div style="font-size:11px;font-weight:700;color:#b8b4b0;margin-bottom:4px">'+aN+'</div>'
          +'<div style="font-size:32px;font-weight:800;color:#f0ede8;font-family:var(--s803-font-head)">'+aS+'</div></div>'
          +'</div></div>'
          +'<div id="s803-comm-feed" style="padding:10px 14px;max-height:320px;overflow-y:auto">'
          +'<div style="text-align:center;padding:20px;color:#333;font-size:11px">Loading commentary…</div>'
          +'</div></div>';
        var icons = {goal:'⚽',yellowcard:'🟨',redcard:'🟥',sub:'🔄',var:'📺',ht:'🔔',ft:'🏁',ko:'🟢',update:'📝'};
        var eventColors = {goal:'#26c96a',yellowcard:'#f5c842',redcard:'#e03030',sub:'#3b9eff',var:'#a855f7',ht:'#f5c842',ft:'#3b9eff',ko:'#26c96a',update:'#1e1e1e'};
        function renderFeed(entries){
          var feed = commWrap.querySelector('#s803-comm-feed'); if(!feed)return;
          if(!entries||!entries.length){feed.innerHTML='<div style="text-align:center;padding:20px;color:#333;font-size:11px">No updates yet</div>';return;}
          feed.innerHTML = entries.slice(0,30).map(function(e){
            var ic=icons[e.type]||'📝', col=eventColors[e.type]||'#1e1e1e';
            return '<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #111;align-items:flex-start">'
              +(e.min?'<div style="font-size:10px;font-weight:800;color:var(--s803-accent);min-width:30px;flex-shrink:0;padding-top:2px">'+e.min+'</div>':'<div style="min-width:30px"></div>')
              +'<div style="font-size:14px;flex-shrink:0;padding-top:1px">'+ic+'</div>'
              +'<div style="flex:1"><div style="font-size:12px;color:#f0ede8;line-height:1.5">'+e.text+'</div>'
              +(e.score&&e.score!=='0-0'?'<div style="font-size:10px;color:'+col+';font-weight:800;margin-top:2px">'+e.score+'</div>':'')
              +'</div></div>';
          }).join('');
        }
        var xc=new XMLHttpRequest(); xc.open('GET',FB_COMM,true);
        xc.onreadystatechange=function(){if(xc.readyState!==4)return;try{var d=JSON.parse(xc.responseText);renderFeed(Array.isArray(d)?d:[]);}catch(e){renderFeed([]);}};
        xc.send(null);
        if(status==='live') setInterval(function(){
          var xp=new XMLHttpRequest();xp.open('GET',FB_COMM,true);
          xp.onreadystatechange=function(){if(xp.readyState!==4)return;try{renderFeed(JSON.parse(xp.responseText)||[]);}catch(e){}};
          xp.send(null);
        }, 30000);
        var tgt = document.querySelector('.blog-posts')||document.querySelector('#main-wrapper')||document.querySelector('.main-wrapper');
        if(tgt) tgt.insertBefore(commWrap, tgt.firstChild);
      });
