  var tQ=[], tB=false;
  function appToast(msg,accent){ tQ.push({msg:msg,accent:accent||'#e03030'}); if(!tB)nxT(); }
  function nxT(){
    if(!tQ.length){tB=false;return;} tB=true;
    var i=tQ.shift(), w=$id('s803-toast-wrap'); if(!w)return;
    var t=document.createElement('div'); t.className='s803-toast';
    t.style.borderLeftColor=i.accent; t.innerHTML=i.msg; w.appendChild(t);
    requestAnimationFrame(function(){requestAnimationFrame(function(){t.classList.add('in');});});
    setTimeout(function(){t.classList.add('out');setTimeout(function(){if(t.parentNode)t.remove();nxT();},250);},2800);
  }
  window.appToast=appToast;

  function haptic(t){
    if(!navigator.vibrate)return;
    if(t==='light')navigator.vibrate(10);
    else if(t==='medium')navigator.vibrate(25);
    else if(t==='heavy')navigator.vibrate([30,10,30]);
    else if(t==='error')navigator.vibrate([50,30,50,30,50]);
    else if(t==='success')navigator.vibrate([10,5,20]);
  }

  function showGoalToast(scorer, team, score){
    var w=$id('s803-toast-wrap'); if(!w)return;
    var t=document.createElement('div');
    t.className='s803-goal-toast';
    t.innerHTML='<div class="gt-icon">⚽</div><div class="gt-content"><div class="gt-headline">GOAL! — '+team+'</div><div class="gt-sub">'+(scorer||'')+'</div></div><div class="gt-score">'+score+'</div>';
    w.appendChild(t);
    haptic('heavy');
    requestAnimationFrame(function(){requestAnimationFrame(function(){t.classList.add('in');});});
    setTimeout(function(){t.classList.add('out');setTimeout(function(){if(t.parentNode)t.remove();},280);},5000);
  }
  window.showGoalToast=showGoalToast;

  var _asData={};
  function attachLongPress(el, getData){
    var timer=null;
    el.addEventListener('touchstart',function(){timer=setTimeout(function(){haptic('medium');showActionSheet(getData());},500);},{passive:true});
    el.addEventListener('touchend',function(){clearTimeout(timer);},{passive:true});
    el.addEventListener('touchmove',function(){clearTimeout(timer);},{passive:true});
  }

  function showActionSheet(data){
    var sheet=$id('s803-action-sheet');
    var title=$id('as-title');
    var actions=$id('as-actions');
    if(!sheet||!title||!actions)return;
    title.textContent=data.title||'Match Options';
    var html='';
    (data.actions||[]).forEach(function(a){
      html+='<button class="as-action'+(a.dest?' as-dest':'')+'" data-href="'+(a.href||'')+'"><div class="as-action-icon '+(a.color||'red')+'">'+(a.icon||'')+'</div><div><div class="as-action-text">'+a.label+'</div>'+(a.sub?'<div class="as-action-sub">'+a.sub+'</div>':'')+'</div></button>';
    });
    actions.innerHTML=html;
    actions.querySelectorAll('.as-action').forEach(function(btn){
      btn.addEventListener('click',function(){
        var href=btn.dataset.href;
        if(href&&href!=='#')window.location.href=href;
        closeActionSheet();
        haptic('light');
      });
    });
    sheet.classList.add('show');
    document.body.style.overflow='hidden';
  }

  function closeActionSheet(){
