  var TT_KEY='s803_tt_done';
  var ttSeq=[
    {target:'nav-scores', text:'⚽ Live Scores — Real-time scores from 9 leagues. Updates every 60 seconds.'},
    {target:'s803-search-btn', text:'🔍 Search — Find any match, team or sport instantly.'},
    {target:'nav-bkm', text:'🔖 Saved — Bookmark posts to read offline anytime.'},
  ];
  var ttIdx=0,ttEl=null;

  function showNextTip(){
    if(ttIdx>=ttSeq.length){localStorage.setItem(TT_KEY,'1');return;}
    if(ttEl&&ttEl.parentNode)ttEl.remove();
    var tip=ttSeq[ttIdx];
    var anchor=$id(tip.target);
    if(!anchor){ttIdx++;showNextTip();return;}
    var rect=anchor.getBoundingClientRect();
    ttEl=document.createElement('div');
    ttEl.className='s803-tooltip';
    ttEl.innerHTML='<button class="tt-close" id="tt-close-btn">×</button><div class="tt-title">Tip '+(ttIdx+1)+' of '+ttSeq.length+'</div><div class="tt-body">'+tip.text+'</div>';
    ttEl.style.bottom=(window.innerHeight - rect.top + 14)+'px';
    ttEl.style.left=Math.max(8,Math.min(window.innerWidth-272,rect.left - 90))+'px';
    document.body.appendChild(ttEl);
    ttEl.querySelector('#tt-close-btn').addEventListener('click',function(){ttIdx++;showNextTip();haptic('light');});
    var autoTimer=setTimeout(function(){ttIdx++;showNextTip();},4000);
    ttEl.querySelector('#tt-close-btn').addEventListener('click',function(){clearTimeout(autoTimer);},{once:true});
  }

  setTimeout(function(){
    if(!localStorage.getItem(TT_KEY)&&nav&&nav.classList.contains('show')){showNextTip();}
  },3500);

