    var sessions=parseInt(localStorage.getItem('s803_sessions')||'0')+1;
    var firstSeen=localStorage.getItem('s803_first_seen')||new Date().toISOString();
    var device=isAndroid?'android':(iOS?'ios':'desktop');
    var installType=SA?'pwa':'browser';
    var pv=parseInt(localStorage.getItem('s803_pageviews')||'0')+1;
    localStorage.setItem('s803_sessions',sessions);
    localStorage.setItem('s803_first_seen',firstSeen);
    localStorage.setItem('s803_last_seen',new Date().toISOString());
    localStorage.setItem('s803_device',device);
    localStorage.setItem('s803_install',installType);
    localStorage.setItem('s803_ua',ua.substring(0,120));
    localStorage.setItem('s803_pageviews',pv);
    gtag('set','user_properties',{install_type:installType,device_type:device,is_pwa:SA?'yes':'no'});
    gtag('event','app_open',{install_type:installType,device_type:device,session_count:sessions,is_pwa:SA?'yes':'no'});
    if(sessions===1)gtag('event','first_open',{install_type:installType,device_type:device});
    if(SA)gtag('event','pwa_launch',{device_type:device,session_count:sessions});
  }
