      +'<button id="s803-admin-close" style="background:#1a1a1a;border:1px solid #222;color:#787470;border-radius:8px;padding:6px 12px;font-size:13px;cursor:pointer;">✕ Close</button>'
      +'</div><div id="s803-admin-body" style="display:flex;flex-direction:column;gap:10px;"></div></div>';
    var d=document.createElement('div'); d.innerHTML=ph; document.body.appendChild(d.firstChild);
    function stat(l,v){return'<div style="background:#111;border:1px solid #222;border-radius:12px;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:13px;color:#b8b4b0;">'+l+'</span><span style="font-family:Oswald,sans-serif;font-size:18px;font-weight:700;color:#f0ede8;">'+v+'</span></div>';}
    function openAdmin(){
      var panel=$id('s803-admin-panel'),body=$id('s803-admin-body'); if(!panel||!body)return;
      var fd=function(iso){try{return new Date(iso).toLocaleString();}catch(e){return'N/A';}};
      body.innerHTML=
        '<div style="background:#1a0000;border:1px solid #3a0000;border-radius:12px;padding:12px 16px;font-size:11px;color:#787470;text-align:center;">View full stats in GA4 → <b style=\'color:#f5c842\'>'+GA_ID+'</b></div>'
        +stat('📱 Install Type',(localStorage.getItem('s803_install')||'browser').toUpperCase())
        +stat('💻 Device',(localStorage.getItem('s803_device')||'unknown').toUpperCase())
        +stat('🔢 Sessions',localStorage.getItem('s803_sessions')||'0')
        +stat('📄 Page Views',localStorage.getItem('s803_pageviews')||'0')
        +stat('🔖 Saved Posts',(function(){try{return JSON.parse(localStorage.getItem('s803_bkm')||'[]').length;}catch(e){return 0;}})())
        +stat('⭐ Fav Teams',(function(){try{return JSON.parse(localStorage.getItem('s803_fav_teams')||'[]').length;}catch(e){return 0;}})())
        +stat('🗓 First Seen',fd(localStorage.getItem('s803_first_seen')))
        +stat('🕐 Last Seen',fd(localStorage.getItem('s803_last_seen')))
        +stat('🖥 PWA Active',SA?'YES ✓':'NO')
        +'<button id="s803-clear-analytics" style="width:100%;padding:14px;background:#1a0000;border:1px solid #400;border-radius:12px;color:#e03030;font-size:13px;font-weight:700;cursor:pointer;margin-top:4px;">🗑 Clear Analytics Data</button>';
      panel.style.display='flex';
      var cb=$id('s803-admin-close'); if(cb)cb.onclick=function(){panel.style.display='none';};
      var cl=$id('s803-clear-analytics'); if(cl)cl.onclick=function(){['s803_sessions','s803_pageviews','s803_first_seen','s803_last_seen','s803_device','s803_install','s803_ua'].forEach(function(k){localStorage.removeItem(k);});panel.style.display='none';appToast('Analytics cleared','#e03030');};
    }
    var tapC=0,tapT=null;
    function sTap(){tapC++;clearTimeout(tapT);tapT=setTimeout(function(){tapC=0;},1500);if(tapC>=5){tapC=0;openAdmin();}}
    setTimeout(function(){
      [$id('nav-home'),qs('.spl-name'),qs('.spl-logo')].forEach(function(el){if(el)el.addEventListener('click',sTap);});
