  var TEAM_ALIASES={
    'Manchester United':['Man Utd','Man United','MUFC'],'Manchester City':['Man City','City','MCFC'],
    'Tottenham Hotspur':['Spurs','Tottenham','THFC'],'Newcastle United':['Newcastle','NUFC','Toon'],
    'West Ham United':['West Ham','Hammers'],'Nottingham Forest':['Nottm Forest','Forest'],
    'Wolverhampton Wanderers':['Wolves'],'Brighton & Hove Albion':['Brighton'],
    'Aston Villa':['Villa','AVFC'],'Arsenal':['Gunners'],'Chelsea':['Blues'],
    'Liverpool':['Reds','LFC'],'Real Madrid':['Madrid','Real'],'FC Barcelona':['Barca','Barcelona'],
    'Atletico Madrid':['Atletico'],'Bayern Munich':['Bayern'],'Borussia Dortmund':['Dortmund','BVB'],
    'Juventus':['Juve'],'AC Milan':['Milan'],'Inter Milan':['Inter'],'Paris Saint-Germain':['PSG'],
  };
  function teamAlts(name){if(!name)return[];var l=[name];if(TEAM_ALIASES[name])l=l.concat(TEAM_ALIASES[name]);var w=name.split(' ')[0];if(w.length>3&&l.indexOf(w)===-1)l.push(w);return l;}
  function isRecentPost(iso){if(!iso)return false;var hrs=(new Date()-new Date(iso))/3600000;return hrs>=-6&&hrs<=36;}
  var _pCache={},_pPend={},_cbN=0;
  function searchMatchPost(home,away,cb){
    var d=new Date();
    var key=d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()+'|'+home+'|'+away;
    if(Object.prototype.hasOwnProperty.call(_pCache,key)){cb(_pCache[key]);return;}
    if(_pPend[key]){_pPend[key].push(cb);return;}
    _pPend[key]=[cb];
    var hK=teamAlts(home),aK=teamAlts(away);
    var q=encodeURIComponent((hK[0]||home)+' '+(aK[0]||away));
    var fn='_s803cb'+(_cbN++);
    window[fn]=function(data){
      delete window[fn];var sc=document.getElementById('_s803sc_'+fn);if(sc)sc.remove();
      var result=null,entries=(data.feed&&data.feed.entry)?data.feed.entry:[];
      for(var i=0;i<entries.length&&!result;i++){
        var e=entries[i],ttl=e.title?e.title['$t']:'',pub=e.published?e.published['$t']:'';
        if(!isRecentPost(pub))continue;
        var tl=ttl.toLowerCase(),url='';
        if(e.link)e.link.forEach(function(l){if(l.rel==='alternate')url=l.href;});
        var hHit=hK.some(function(k){return k&&tl.indexOf(k.toLowerCase())!==-1;});
        var aHit=aK.some(function(k){return k&&tl.indexOf(k.toLowerCase())!==-1;});
        var cats=e.category||[];
        var hasLiveLabel=cats.some(function(c){return c.term&&c.term.toLowerCase()===LIVE_LABEL.toLowerCase();});
        if(hHit&&aHit){result={url:url,title:ttl};break;}
        if((hHit||aHit)&&(hasLiveLabel||/live|stream|watch/i.test(tl)))result={url:url,title:ttl};
      }
      _pCache[key]=result;(_pPend[key]||[]).forEach(function(f){f(result);});delete _pPend[key];
    };
    var sc=document.createElement('script');sc.id='_s803sc_'+fn;
    sc.src=SITE_URL+'/feeds/posts/default?q='+q+'&max-results=10&orderby=published&alt=json&callback='+fn;
    sc.onerror=function(){_pCache[key]=null;(_pPend[key]||[]).forEach(function(f){f(null);});delete _pPend[key];delete window[fn];};
    document.head.appendChild(sc);
  }

  function upgradeWatchBtn(home,homeFull,away,awayFull,card){
    var btn=card.querySelector('.score-watch-btn'); if(!btn)return;
    searchMatchPost(homeFull||home,awayFull||away,function(r){
      if(!r||!r.url)return;
      btn.href=r.url;
      var icon=btn.querySelector('.swb-icon');
      var dot=btn.querySelector('.swb-dot');
      if(icon&&dot){btn.innerHTML='';btn.appendChild(icon);btn.appendChild(dot);btn.appendChild(document.createTextNode('🔴 Live Stream Found — Watch Now'));}
      else btn.innerHTML='🔴 Live Stream Found — Watch Now';
      btn.style.background='linear-gradient(135deg,rgba(224,48,48,0.28),rgba(224,48,48,0.12))';
      btn.addEventListener('click',function(){trackWatchLive(homeFull||home,awayFull||away,'scores_card');},{once:true});
    });
  }

