  var savedTheme=localStorage.getItem('s803_theme')||'dark';
  var savedAccent=localStorage.getItem('s803_accent')||'default';
  var isLight=savedTheme==='light';
  function checkAutoNight(){if(localStorage.getItem('s803_theme'))return;var h=new Date().getHours();if(h>=22||h<6){isLight=false;applyTheme(false);}}
  function applyTheme(light){isLight=light;document.body.classList.toggle('s803-light',light);var btn=$id('s803-theme-btn');if(btn)btn.textContent=light?'☀️':'🌙';var tgl=$id('tp-toggle');if(tgl)tgl.classList.toggle('on',!light);localStorage.setItem('s803_theme',light?'light':'dark');}
  function applyAccent(theme){if(theme==='default')document.body.removeAttribute('data-theme');else document.body.setAttribute('data-theme',theme);qsa('.tp-swatch').forEach(function(s){s.classList.toggle('active',s.dataset.theme===theme);});localStorage.setItem('s803_accent',theme);}
  applyTheme(isLight);applyAccent(savedAccent);checkAutoNight();

  /* ===== FIX: THEME BUTTON HANDLER ===== */
  var themeBtn = $id('s803-theme-btn');
  var themePanel = $id('s803-theme-panel');
  if(themeBtn && themePanel) {
    themeBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      themePanel.classList.toggle('show');
      haptic('light');
    });
  }

  if(themePanel){
    qsa('.tp-swatch').forEach(function(s){s.addEventListener('click',function(){applyAccent(s.dataset.theme);haptic('light');});});
    var tgl=$id('tp-toggle');if(tgl)tgl.addEventListener('click',function(){applyTheme(!isLight);haptic('light');});
  }

  function buildQR(url){var bg=isLight?'ffffff':'111111',fg=isLight?'1a1a1a':'f0ede8';return'<img src="https://api.qrserver.com/v1/create-qr-code/?size=160x160&bgcolor='+bg+'&color='+fg+'&data='+encodeURIComponent(url+'?install=1')+'" alt="QR" style="width:160px;height:160px;border-radius:8px;display:block"/>';}
  function showAppLink(btnEl){if(APP_LINK&&btnEl){btnEl.href=APP_LINK;btnEl.style.display='block';btnEl.target='_blank';btnEl.rel='noopener';}}

  /* — NETWORK — */
  function checkNetwork(){var nb=$id('s803-net-bar'),msg=$id('net-msg');if(!nb)return;if(!navigator.onLine){nb.classList.add('show','offline');if(msg)msg.textContent="📴 You're offline";nb.querySelector('.net-icon').textContent='📴';}else{nb.classList.remove('offline');var conn=navigator.connection||navigator.mozConnection||navigator.webkitConnection;if(conn){var slow=conn.effectiveType==='2g'||conn.effectiveType==='slow-2g'||(conn.downlink&&conn.downlink<0.5);if(slow){nb.classList.add('show');if(msg)msg.textContent='Slow connection – videos may buffer';setTimeout(function(){nb.classList.remove('show');},5000);}else nb.classList.remove('show');}else nb.classList.remove('show');}}
  window.addEventListener('offline',checkNetwork);
