  /* — BOOKMARKS — */
  function getBookmarks(){try{return JSON.parse(localStorage.getItem('s803_bkm')||'[]');}catch(e){return[];}}
  function saveBookmarks(b){localStorage.setItem('s803_bkm',JSON.stringify(b));}
  function isBookmarked(url){return getBookmarks().some(function(b){return b.url===url;});}
  function toggleBookmark(url,title,thumb,date){
    var bkms=getBookmarks(),idx=bkms.findIndex(function(b){return b.url===url;});
    if(idx!==-1){bkms.splice(idx,1);saveBookmarks(bkms);updateBkmBadge();trackBookmark('removed',title);appToast('Removed from saved posts','#888');haptic('light');return false;}
    else{bkms.unshift({url:url,title:title,thumb:thumb||'',date:date||''});if(bkms.length>50)bkms=bkms.slice(0,50);saveBookmarks(bkms);updateBkmBadge();trackBookmark('saved',title);appToast('🔖 Saved to your posts!','#3b9eff');haptic('success');return true;}
  }
  function updateBkmBadge(){var bkms=getBookmarks(),bdg=$id('bkm-bdg');if(bdg){bdg.textContent=bkms.length;bdg.classList.toggle('show',bkms.length>0);}var cnt=$id('bkm-count');if(cnt)cnt.textContent=bkms.length+' bookmark'+(bkms.length!==1?'s':'');}
