    if(!bkms.length){feed.innerHTML='<div class="bkm-empty"><span>🔖</span>No saved posts yet.<br/>Tap the bookmark icon on any post to save it here.</div>';return;}
    var html='';
    bkms.forEach(function(b){var imgH=b.thumb?'<img class="bkm-thumb" src="'+b.thumb+'" alt="" loading="lazy" onerror="this.outerHTML=\'<div class=bkm-thumb-placeholder>📺</div>\'">':'<div class="bkm-thumb-placeholder">📺</div>';html+='<a class="bkm-card" href="'+b.url+'">'+imgH+'<div class="bkm-info"><div class="bkm-card-title">'+b.title+'</div><div class="bkm-card-date">'+b.date+'</div></div><button class="bkm-remove" data-url="'+b.url+'" title="Remove">×</button></a>';});
    feed.innerHTML=html;
    feed.querySelectorAll('.bkm-remove').forEach(function(btn){btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();saveBookmarks(getBookmarks().filter(function(b){return b.url!==btn.dataset.url;}));updateBkmBadge();renderBookmarks();haptic('light');});});
  }
  function injectBookmarkBtn(){
    if(!isPostPage)return;
    qsa('.post-body,.entry-content,[itemprop="articleBody"]').forEach(function(body){
      if(body.querySelector('.bkm-save-btn'))return;
      var url=window.location.href,title=document.title;
      var thumb=(function(){var img=body.querySelector('img');return img?img.src:'';})();
      var date=(function(){var dt=qs('.date-header,.post-timestamp,time,[itemprop="datePublished"]');return dt?(dt.getAttribute('datetime')?new Date(dt.getAttribute('datetime')).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):dt.textContent.trim()):'';})();
      var saved=isBookmarked(url);
      var btn=document.createElement('button');
      btn.className='bkm-save-btn'+(saved?' saved':'');
      btn.innerHTML=saved?'🔖 Saved':'🔖 Save Post';
      btn.addEventListener('click',function(){var ns=toggleBookmark(url,title,thumb,date);btn.innerHTML=ns?'🔖 Saved':'🔖 Save Post';btn.classList.toggle('saved',ns);});
      var shareBar=body.querySelector('.s803-share-bar');
      if(shareBar)shareBar.insertBefore(btn,shareBar.firstChild);else body.appendChild(btn);
    });
