          card.querySelectorAll('a').forEach(function(a){if(a.href&&a.href.indexOf('/search/label/'+encodeURIComponent(LIVE_LABEL))!==-1)isLC=true;});
          if(!isLC||card.closest('.s803-card-wrap'))return;
          var inner=card.innerHTML,target=APP_LINK||(SITE_URL+'?install=1');
          card.innerHTML='<div class="s803-card-blur">'+inner+'</div><a class="s803-card-badge" href="'+target+'"><div class="s803-card-badge-icon">SPORTS<br/>803</div><div class="s803-card-badge-label">🔒 App Only</div><div class="s803-card-badge-sub">Tap to install &amp; watch free</div></a>';
          card.classList.add('s803-card-wrap');card.style.cssText+=';position:relative;overflow:hidden;';
        });
