    if(isAndroid){if(ipSteps)ipSteps.innerHTML='<div class="ip-steps-title">Install on Android</div>'+sH(1,'Tap Install above','Or tap ⋮ in Chrome → "Add to Home screen"')+sH(2,'Tap "Install" on the prompt','Sports 803 icon appears on your home screen')+sH(3,'Open Sports 803 & enjoy!','Full Live TV & exclusive content unlocked');if(ipBtn)ipBtn.addEventListener('click',function(){haptic('medium');if(window._s803DeferredPrompt)window._s803DeferredPrompt.prompt();else{if(ipSteps)ipSteps.scrollIntoView({behavior:'smooth'});appToast('Tap ⋮ → "Add to Home screen" in Chrome','#e03030');}});}
    else if(iOS){if(ipBtn)ipBtn.classList.add('hidden');if(ipSteps)ipSteps.innerHTML='<div class="ip-steps-title">Install on iPhone / iPad</div>'+sH(1,'Open in Safari','Chrome on iOS cannot install — switch to Safari first')+sH(2,'Tap the Share button ▲','Bottom of screen')+sH(3,'Tap "Add to Home Screen"','Scroll down in the share sheet')+sH(4,'Tap Add — done!','Sports 803 appears on your home screen');}
    else{if(ipSteps)ipSteps.innerHTML='<div class="ip-steps-title">Install on Desktop</div>'+sH(1,'Click ⊕ install icon in Chrome','Right side of the address bar')+sH(2,'Click "Install"','Sports 803 opens as standalone desktop app')+sH(3,'📷 Or scan QR on your phone','Install on mobile for on-the-go access');if(ipBtn)ipBtn.addEventListener('click',function(){haptic('medium');if(window._s803DeferredPrompt)window._s803DeferredPrompt.prompt();else appToast('Look for ⊕ install icon in Chrome address bar','#e03030');});if(ipQR)ipQR.classList.add('show');if(ipQRI)ipQRI.innerHTML=buildQR(SITE_URL);}
    var ipOpen=$id('ip-open-app');if(ipOpen)ipOpen.addEventListener('click',function(e){e.preventDefault();window.location.href=SITE_URL;});
