  var scoresPanel=$id('s803-scores-panel'),scoresFeed=$id('scores-feed'),scoresUpdate=$id('scores-update-time');
  var scoresCache={},currentLeague='eng.1',showFavsOnly=false;
  var _prevScores={};

  function getFavTeams(){try{return JSON.parse(localStorage.getItem('s803_fav_teams')||'[]');}catch(e){return[];}}
  function toggleFavTeam(name){var favs=getFavTeams(),idx=favs.indexOf(name);if(idx!==-1)favs.splice(idx,1);else favs.push(name);localStorage.setItem('s803_fav_teams',JSON.stringify(favs));haptic(idx===-1?'success':'light');return idx===-1;}
  function isFavTeam(name){return getFavTeams().indexOf(name)!==-1;}

  function fmtScoreTime(ev){
    var s=ev.status?ev.status.type:null;if(!s)return'';var n=s.name||'';
    if(/STATUS_IN_PROGRESS|STATUS_FIRST_HALF|STATUS_SECOND_HALF|STATUS_HALFTIME/.test(n)){var cl=ev.status.displayClock||'';return cl?'<span class="score-status-live">'+cl+'</span>':'<span class="score-status-live">LIVE</span>';}
    if(n==='STATUS_FULL_TIME'||n==='STATUS_FINAL')return'<span class="score-status-ft">FT</span>';
    if(n==='STATUS_POSTPONED')return'<span class="score-status-ft">PPD</span>';
    if(n==='STATUS_CANCELED')return'<span class="score-status-ft">CAN</span>';
    var d=ev.date?new Date(ev.date):null;
    if(d){var hh=d.getHours(),mm=d.getMinutes();return'<span class="score-status-upcoming">'+(hh<10?'0':'')+hh+':'+(mm<10?'0':'')+mm+'</span>';}
    return'<span class="score-status-upcoming">TBC</span>';
  }
  function isLiveEvent(ev){var s=ev.status?ev.status.type:null;if(!s)return false;return/STATUS_IN_PROGRESS|STATUS_FIRST_HALF|STATUS_SECOND_HALF|STATUS_HALFTIME/.test(s.name||'');}

  function buildCountdown(dateStr){
    if(!dateStr)return'';var target=new Date(dateStr),now=new Date(),diff=target-now;
    if(diff<=0||diff>86400000)return'';
    var hrs=Math.floor(diff/3600000),mins=Math.floor((diff%3600000)/60000),secs=Math.floor((diff%60000)/1000);
    return'<div class="score-countdown"><span class="countdown-label">Kicks off in</span><div class="countdown-val"><div class="cd-unit"><div class="cd-num">'+String(hrs).padStart(2,'0')+'</div><div class="cd-lbl">hr</div></div><div class="cd-sep">:</div><div class="cd-unit"><div class="cd-num">'+String(mins).padStart(2,'0')+'</div><div class="cd-lbl">min</div></div><div class="cd-sep">:</div><div class="cd-unit"><div class="cd-num">'+String(secs).padStart(2,'0')+'</div><div class="cd-lbl">sec</div></div></div></div>';
  }
  setInterval(function(){
    qsa('.score-countdown .countdown-val').forEach(function(cv){var card=cv.closest('.score-card');if(!card)return;var da=card.dataset.matchDate;if(!da)return;var diff=new Date(da)-new Date();if(diff<=0)return;var hrs=Math.floor(diff/3600000),mins=Math.floor((diff%3600000)/60000),secs=Math.floor((diff%60000)/1000);var nums=cv.querySelectorAll('.cd-num');if(nums[0])nums[0].textContent=String(hrs).padStart(2,'0');if(nums[1])nums[1].textContent=String(mins).padStart(2,'0');if(nums[2])nums[2].textContent=String(secs).padStart(2,'0');});
  },1000);

  function renderScoresSkeleton(){
    if(!scoresFeed)return;
    var h='';for(var i=0;i<4;i++)h+='<div class="skel-score-card"><div class="skel-row" style="margin-bottom:8px"><div class="s803-skel skel-line" style="width:120px"></div><div class="s803-skel skel-line" style="width:40px;margin-left:auto"></div></div><div class="skel-row" style="justify-content:space-between;padding:0 8px"><div class="skel-row" style="gap:8px;flex:1"><div class="s803-skel skel-circle"></div><div class="s803-skel skel-line" style="width:70px"></div></div><div style="display:flex;gap:8px"><div class="s803-skel skel-score-num"></div><div class="s803-skel skel-score-num"></div></div><div class="skel-row" style="gap:8px;flex:1;justify-content:flex-end"><div class="s803-skel skel-line" style="width:70px"></div><div class="s803-skel skel-circle"></div></div></div></div>';
    scoresFeed.innerHTML=h;
  }

  function buildPossessionRings(hName, aName, hPct, aPct){
    var hC=145*(1-hPct/100), aC=145*(1-aPct/100);
    return '<div class="score-possession">'
      +'<div class="poss-ring-wrap">'
      +'<div class="poss-ring"><svg viewBox="0 0 52 52" width="52" height="52"><circle class="pr-track" cx="26" cy="26" r="23"/><circle class="pr-fill pr-fill-h" cx="26" cy="26" r="23" stroke-dashoffset="'+hC+'"/></svg>'
      +'<div class="poss-ring-label"><div class="poss-pct" style="color:var(--s803-accent)">'+hPct+'%</div><div class="poss-sub">Poss</div></div></div>'
      +'<div class="poss-team" style="color:var(--s803-accent)">'+hName+'</div></div>'
      +'<div class="poss-vs">VS</div>'
      +'<div class="poss-ring-wrap">'
      +'<div class="poss-ring"><svg viewBox="0 0 52 52" width="52" height="52"><circle class="pr-track" cx="26" cy="26" r="23"/><circle class="pr-fill pr-fill-a" cx="26" cy="26" r="23" stroke-dashoffset="'+aC+'"/></svg>'
      +'<div class="poss-ring-label"><div class="poss-pct" style="color:var(--s803-blue)">'+aPct+'%</div><div class="poss-sub">Poss</div></div></div>'
      +'<div class="poss-team" style="color:var(--s803-blue)">'+aName+'</div></div>'
      +'</div>';
  }

  function buildStatBars(stats){
    if(!stats||!stats.length)return'';
    var html='<div class="score-stat-bars">';
    stats.forEach(function(s){
      html+='<div class="ssb-row">'
        +'<span class="ssb-val">'+s.hv+'</span>'
        +'<div class="ssb-track"><div class="ssb-fill-h" style="width:'+s.hp+'%"></div></div>'
        +'<span class="ssb-label">'+s.label+'</span>'
        +'<div class="ssb-track"><div class="ssb-fill-a" style="width:'+s.ap+'%"></div></div>'
        +'<span class="ssb-val away">'+s.av+'</span>'
        +'</div>';
    });
    html+='</div>';
    return html;
  }

  function buildTimeline(events, clock){
    if(!events||!events.length)return'';
    var pct=Math.min(100,Math.round((parseInt(clock)||0)/90*100));
    var html='<div class="score-timeline"><div class="stl-bar"><div class="stl-fill" style="width:'+pct+'%"></div></div><div class="stl-events">';
    events.slice(0,6).forEach(function(ev){
      var cls='stl-ev'+(ev.type==='goal'?' goal':ev.type==='yellowcard'?' ycard':ev.type==='redcard'?' rcard':'');
      var icon=ev.type==='goal'?'⚽':ev.type==='yellowcard'?'🟨':'🟥';
      html+='<div class="'+cls+'">'+icon+' '+ev.min+'\' '+ev.player+'</div>';
    });
    html+='</div></div>';
    return html;
  }

  function detectGoals(ev, hName, aName, hScore, aScore){
    var key=ev.id||ev.uid||'';if(!key)return;
    var prev=_prevScores[key];
    if(prev){
      if(parseInt(hScore)>parseInt(prev.h))showGoalToast('',hName,hScore+' – '+aScore);
      else if(parseInt(aScore)>parseInt(prev.a))showGoalToast('',aName,hScore+' – '+aScore);
    }
    _prevScores[key]={h:hScore,a:aScore};
  }

  function renderScores(data){
    if(!scoresFeed)return;
    var events=data.events||[];
    var favs=getFavTeams();
    if(showFavsOnly&&favs.length)events=events.filter(function(ev){var c=ev.competitions?ev.competitions[0]:null;if(!c)return false;return(c.competitors||[]).some(function(t2){return t2.team&&favs.indexOf(t2.team.shortDisplayName||t2.team.displayName||'')!==-1;});});
    if(!events.length){scoresFeed.innerHTML=showFavsOnly?'<div class="scores-empty"><span>⭐</span>No matches for your favourite teams.</div>':'<div class="scores-empty"><span>⚽</span>No matches found today.<br/>Check back closer to kick-off.</div>';return;}
    events.sort(function(a,b){var al=isLiveEvent(a)?0:1,bl=isLiveEvent(b)?0:1;if(al!==bl)return al-bl;return new Date(a.date)-new Date(b.date);});
    var html='',liveLink=SITE_URL+'/search/label/'+encodeURIComponent(LIVE_LABEL);
    var hasLive=events.some(isLiveEvent);
    if(hasLive)html+='<div class="scores-date-label">🔴 Live Now</div>';

    events.forEach(function(ev){
      var comps=ev.competitions?ev.competitions[0]:null;if(!comps)return;
      var statusHtml=fmtScoreTime(ev);
      var teams=comps.competitors||[];
      var home=teams.find(function(t){return t.homeAway==='home';})||teams[0]||{};
      var away=teams.find(function(t){return t.homeAway==='away';})||teams[1]||{};
      var hScore=home.score!==undefined?home.score:'-',aScore=away.score!==undefined?away.score:'-';
      var hName=home.team?(home.team.shortDisplayName||home.team.displayName||'Home'):'Home';
      var aName=away.team?(away.team.shortDisplayName||away.team.displayName||'Away'):'Away';
      var hFull=home.team?(home.team.displayName||hName):'';
      var aFull=away.team?(away.team.displayName||aName):'';
      var hLogo=home.team&&home.team.logo?home.team.logo:'';
      var aLogo=away.team&&away.team.logo?away.team.logo:'';
      var hFav=isFavTeam(hName),aFav=isFavTeam(aName);
      var hLogoH=hLogo?'<div class="score-team-badge"><img src="'+hLogo+'" alt="" loading="lazy" onerror="this.parentNode.innerHTML=\'⚽\'"/></div>':'<div class="score-team-badge">⚽</div>';
      var aLogoH=aLogo?'<div class="score-team-badge"><img src="'+aLogo+'" alt="" loading="lazy" onerror="this.parentNode.innerHTML=\'⚽\'"/></div>':'<div class="score-team-badge">⚽</div>';
      var upcoming=!isLiveEvent(ev)&&ev.date&&(new Date(ev.date)-new Date())>0;
      var countdown=upcoming?buildCountdown(ev.date):'';
      var matchDate=ev.date?(' data-match-date="'+ev.date+'"'):'';
      var live=isLiveEvent(ev);

      if(live)detectGoals(ev,hName,aName,hScore,aScore);

      var statBarsHtml='',possHtml='',timelineHtml='';
      if(live&&comps.statistics){
        var rawStats=comps.statistics;
        var findStat=function(abbr){var s=rawStats.find(function(x){return x.abbreviation===abbr||x.name===abbr;});return s?s.teams||[]:[];};
        var possTeams=findStat('possessionPct');
        if(possTeams.length>=2){
          var hPoss=Math.round(parseFloat(possTeams[0].value||0)),aPoss=100-hPoss;
          possHtml=buildPossessionRings(hName,aName,hPoss,aPoss);
        }
        var shotsOnTarget=findStat('shotsOnTarget'),passes=findStat('totalPasses');
        var statArr=[];
        if(shotsOnTarget.length>=2){var hSh=parseInt(shotsOnTarget[0].value||0),aSh=parseInt(shotsOnTarget[1].value||0),tot=hSh+aSh||1;statArr.push({label:'Shots on Target',hv:hSh,av:aSh,hp:Math.round(hSh/tot*100),ap:Math.round(aSh/tot*100)});}
        if(passes.length>=2){var hP=parseInt(passes[0].value||0),aP=parseInt(passes[1].value||0),totP=hP+aP||1;statArr.push({label:'Passes',hv:hP,av:aP,hp:Math.round(hP/totP*100),ap:Math.round(aP/totP*100)});}
        if(statArr.length)statBarsHtml=buildStatBars(statArr);
      }

      if(live){
        var evArr=[];
        if(comps.scoringPlays)comps.scoringPlays.forEach(function(sp){evArr.push({type:'goal',min:sp.clock?sp.clock.displayValue||'':'' ,player:(sp.team&&sp.team.shortDisplayName)||''});});
        var clock=ev.status&&ev.status.displayClock?ev.status.displayClock.replace('\'',' ').trim():'0';
        if(evArr.length)timelineHtml=buildTimeline(evArr,clock);
      }

      html+='<div class="score-card'+(live?' s803-live':'')+'" data-home="'+hFull.replace(/"/g,'')+'" data-away="'+aFull.replace(/"/g,'')+'"'+matchDate+'>'
        +'<div class="score-card-scan"></div>'
        +'<div class="score-card-header"><span class="score-comp">'+(comps.venue?comps.venue.fullName||(ev.name||'Match'):(ev.name||'Match'))+'</span>'+statusHtml+'</div>'
        +'<div class="score-match">'
        +'<div class="score-team">'+hLogoH+'<div class="score-team-name">'+(hFav?'⭐ ':'')+hName+'</div></div>'
        +'<div class="score-center"><div class="score-numbers"><span class="score-num">'+hScore+'</span><span class="score-sep">–</span><span class="score-num">'+aScore+'</span></div><div class="score-time">'+statusHtml.replace(/<[^>]+>/g,'')+'</div></div>'
        +'<div class="score-team away">'+aLogoH+'<div class="score-team-name">'+aName+(aFav?' ⭐':'')+'</div></div>'
        +'</div>'
        +(countdown||'')
        +possHtml
        +statBarsHtml
        +timelineHtml
        +(live?'<a class="score-watch-btn" href="'+liveLink+'" target="_blank" rel="noopener"><div class="swb-icon"></div><div class="swb-dot"></div>Watch Live on Sports 803</a>':'')
        +'<div style="display:flex;">'
        +'<button class="score-fav-btn '+(hFav?'active':'')+'" data-team="'+hName+'" title="Favourite '+hName+'">⭐</button>'
        +'<button class="score-fav-btn '+(aFav?'active':'')+'" data-team="'+aName+'" title="Favourite '+aName+'" style="margin-left:auto">⭐</button>'
        +'</div></div>';
    });

    scoresFeed.innerHTML=html;

    requestAnimationFrame(function(){
      qsa('.score-card[data-home]',scoresFeed).forEach(function(card){
        var h=card.dataset.home,a=card.dataset.away;
        if(h&&a&&card.querySelector('.score-watch-btn'))upgradeWatchBtn(h,h,a,a,card);
        attachLongPress(card,function(){
          var hN=card.dataset.home||'Home',aN=card.dataset.away||'Away';
          var watchLink=(card.querySelector('.score-watch-btn')||{}).href||liveLink;
          showActionSheet({
            title:hN+' vs '+aN,
            actions:[
              {icon:'📺',label:'Watch Live',sub:'Open live stream',color:'red',href:watchLink},
              {icon:'⭐',label:'Favourite Home Team',sub:hN,color:'gold',href:'#'},
              {icon:'⭐',label:'Favourite Away Team',sub:aN,color:'gold',href:'#'},
              {icon:'🔗',label:'Share Match',sub:'Copy & share link',color:'green',href:'#'},
            ]
          });
        });
      });
    });

    qsa('.score-fav-btn').forEach(function(btn){
      btn.addEventListener('click',function(){
        var name=btn.dataset.team;
        var nowFav=toggleFavTeam(name);
        btn.classList.toggle('active',nowFav);
        trackFavTeam(name,nowFav?'added':'removed');
        appToast(nowFav?'⭐ '+name+' added to My Teams':'Removed from My Teams',nowFav?'#f5c842':'#888');
        updateMiniScore(data.events||[]);
      });
    });

    if(scoresUpdate){var now=new Date();scoresUpdate.textContent='Updated '+now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});}
    updateMiniScore(data.events||[]);
    updateTicker(data.events||[]);
  }

  /* — MINI SCORE — */
  function updateMiniScore(events){
    var live=events.find(isLiveEvent),mini=$id('s803-mini-score');if(!mini)return;
    if(!live||!scoresPanel||scoresPanel.classList.contains('show')){mini.classList.remove('show');return;}
    var comps=live.competitions?live.competitions[0]:null;if(!comps)return;
    var teams=comps.competitors||[];
    var home=teams.find(function(t){return t.homeAway==='home';})||teams[0]||{};
    var away=teams.find(function(t){return t.homeAway==='away';})||teams[1]||{};
    var hName=home.team?(home.team.shortDisplayName||home.team.displayName||'H'):'H';
    var aName=away.team?(away.team.shortDisplayName||away.team.displayName||'A'):'A';
    var n=$id('mini-match-name');if(n)n.textContent=hName+' vs '+aName;
    var sc=$id('mini-score-nums');if(sc)sc.textContent=(home.score!==undefined?home.score:'0')+' – '+(away.score!==undefined?away.score:'0');
    var tm=$id('mini-score-time');if(tm)tm.textContent=live.status?live.status.displayClock||'LIVE':'LIVE';
    mini.classList.add('show');
  }
  var miniClose=$id('mini-score-close');
  if(miniClose)miniClose.addEventListener('click',function(){$id('s803-mini-score').classList.remove('show');});
  var miniScore=$id('s803-mini-score');
  if(miniScore)miniScore.addEventListener('click',function(e){if(e.target.classList.contains('mini-close'))return;var nb=$id('nav-scores');if(nb)nb.click();});

  /* — LIVE TICKER — */
  var _tickerLinks={};
  function updateTicker(events){
    var ticker=$id('s803-ticker'),inner=$id('ticker-inner');
    if(!ticker||!inner)return;
    var liveEvts=events.filter(isLiveEvent);
    if(!liveEvts.length){ticker.classList.remove('show');return;}
    var fallbackLink=SITE_URL+'/search/label/'+encodeURIComponent(LIVE_LABEL);
    var html='';
    liveEvts.forEach(function(ev,idx){
      var comps=ev.competitions?ev.competitions[0]:null;if(!comps)return;
      var teams=comps.competitors||[];
      var home=teams.find(function(t){return t.homeAway==='home';})||teams[0]||{};
      var away=teams.find(function(t){return t.homeAway==='away';})||teams[1]||{};
      var hName=home.team?(home.team.shortDisplayName||home.team.displayName||'H'):'H';
      var aName=away.team?(away.team.shortDisplayName||away.team.displayName||'A'):'A';
      var hFull=home.team?(home.team.displayName||hName):hName;
      var aFull=away.team?(away.team.displayName||aName):aName;
      var hS=home.score!==undefined?home.score:'0',aS=away.score!==undefined?away.score:'0';
      var clock=ev.status&&ev.status.displayClock?ev.status.displayClock:'LIVE';
      var existingLink=_tickerLinks[hFull+'|'+aFull]||fallbackLink;
      html+='<a class="ticker-item" href="'+existingLink+'" target="_blank" rel="noopener" data-ticker-idx="'+idx+'" data-ticker-h="'+hFull+'" data-ticker-a="'+aFull+'">'
        +'<span class="ticker-live-tag">'+clock+'</span>'
        +'<span class="ticker-teams">'+hName+' <span class="ticker-score">'+hS+'–'+aS+'</span> '+aName+'</span>'
        +'</a>';
    });
    inner.innerHTML=html+html;
    ticker.classList.add('show');
    qsa('.ticker-item[data-ticker-idx]',inner).forEach(function(item){
      var hFull=item.dataset.tickerH,aFull=item.dataset.tickerA;if(!hFull||!aFull)return;
      searchMatchPost(hFull,aFull,function(r){
        if(!r||!r.url)return;_tickerLinks[hFull+'|'+aFull]=r.url;
        qsa('.ticker-item[data-ticker-h="'+hFull+'"][data-ticker-a="'+aFull+'"]',inner).forEach(function(a){a.href=r.url;a.classList.add('ticker-found');a.addEventListener('click',function(){trackWatchLive(hFull,aFull,'ticker');},{once:true});});
      });
    });
  }

  var ALL_TICKER_LEAGUES = window._s803TickerLeagues || ['eng.1','esp.1','uefa.champions','ita.1','ger.1','fra.1','usa.1','eng.2','uefa.europa'];
  function loadAllTickerLeagues(){
    ALL_TICKER_LEAGUES.forEach(function(league){
      fetch('https://site.api.espn.com/apis/site/v2/sports/soccer/'+league+'/scoreboard')
        .then(function(r){return r.json();}).then(function(data){
          var liveEvs=(data.events||[]).filter(isLiveEvent);if(!liveEvs.length)return;
          if(!window._s803AllLiveEvents)window._s803AllLiveEvents=[];
          liveEvs.forEach(function(ev){if(!window._s803AllLiveEvents.some(function(e){return e.id===ev.id;}))window._s803AllLiveEvents.push(ev);});
          updateTicker(window._s803AllLiveEvents);
        }).catch(function(){});
    });
  }

  function getTodayStr(){var d=new Date(),m=d.getMonth()+1,dd=d.getDate();return''+d.getFullYear()+(m<10?'0':'')+m+(dd<10?'0':'')+dd;}

  function loadScores(league){
    league=league||currentLeague;renderScoresSkeleton();
    fetch('https://site.api.espn.com/apis/site/v2/sports/soccer/'+league+'/scoreboard')
      .then(function(r){return r.json();}).then(function(data){scoresCache[league]=data;renderScores(data);})
      .catch(function(){
        fetch('https://site.api.espn.com/apis/site/v2/sports/soccer/'+league+'/scoreboard?dates='+getTodayStr())
          .then(function(r){return r.json();}).then(function(data){renderScores(data);})
          .catch(function(){if(scoresFeed)scoresFeed.innerHTML='<div class="scores-empty"><span>⚠️</span>Scores unavailable.<br/>Check your connection &amp; try again.</div>';});
      });
  }

  (function syncLeaguePills(){
    var active = window._s803TickerLeagues;
    if(!active || !active.length) return;
    qsa('.slp-pill').forEach(function(pill){
      var lg = pill.dataset.league;
      if(lg && active.indexOf(lg) === -1) pill.style.display = 'none';
    });
    if(active.indexOf(currentLeague) === -1 && active.length) currentLeague = active[0];
  })();

  qsa('.slp-pill').forEach(function(pill){
    pill.addEventListener('click',function(){
      qsa('.slp-pill').forEach(function(p){p.classList.remove('active');});
      pill.classList.add('active');
      currentLeague=pill.dataset.league;
      haptic('light');
      loadScores(currentLeague);
    });
  });

  var navScoresBtn=$id('nav-scores');
  if(navScoresBtn){navScoresBtn.addEventListener('click',function(){closeAllPanels();navScoresBtn.classList.add('active');var scoresBdg=$id('scores-bdg');if(scoresBdg)scoresBdg.classList.remove('show');if(scoresPanel){scoresPanel.classList.add('show');if(!scoresCache[currentLeague])loadScores(currentLeague);var mini=$id('s803-mini-score');if(mini)mini.classList.remove('show');haptic('light');}trackScoresOpen(currentLeague);});}

  var refreshBtn=$id('scores-refresh-btn');
  if(refreshBtn)refreshBtn.addEventListener('click',function(){refreshBtn.classList.add('spinning');scoresCache={};loadScores(currentLeague);setTimeout(function(){refreshBtn.classList.remove('spinning');},1200);appToast('✅ Scores refreshed','#26c96a');haptic('medium');});

  var favAllBtn=$id('fav-all-btn'),favOnlyBtn=$id('fav-only-btn');
  if(favAllBtn)favAllBtn.addEventListener('click',function(){showFavsOnly=false;favAllBtn.classList.add('active');favOnlyBtn.classList.remove('active');if(scoresCache[currentLeague])renderScores(scoresCache[currentLeague]);haptic('light');});
  if(favOnlyBtn)favOnlyBtn.addEventListener('click',function(){showFavsOnly=true;favOnlyBtn.classList.add('active');favAllBtn.classList.remove('active');if(scoresCache[currentLeague])renderScores(scoresCache[currentLeague]);else loadScores(currentLeague);haptic('light');});

  setInterval(function(){
    if(scoresPanel&&scoresPanel.classList.contains('show'))loadScores(currentLeague);
    else{fetch('https://site.api.espn.com/apis/site/v2/sports/soccer/'+currentLeague+'/scoreboard').then(function(r){return r.json();}).then(function(data){scoresCache[currentLeague]=data;updateTicker(data.events||[]);updateMiniScore(data.events||[]);}).catch(function(){});}
  },60000);

  setTimeout(function(){
    fetch('https://site.api.espn.com/apis/site/v2/sports/soccer/eng.1/scoreboard')
      .then(function(r){return r.json();}).then(function(data){scoresCache['eng.1']=data;updateTicker(data.events||[]);updateMiniScore(data.events||[]);}).catch(function(){});
    setTimeout(loadAllTickerLeagues,2000);
  },1500);

  window.addEventListener('popstate',function(){if(scoresPanel)scoresPanel.classList.remove('show');});

  /* — SWIPE BETWEEN POSTS — */
  if(isPostPage){
    var prevLink=null,nextLink=null;
    var olderEl=qs('.blog-pager-older-link,.older-link,a[id*="Blog1_older"]');
    var newerEl=qs('.blog-pager-newer-link,.newer-link,a[id*="Blog1_newer"]');
    qsa('a').forEach(function(a){var txt=a.textContent.trim().toLowerCase();if(txt.indexOf('older')!==-1||txt.indexOf('previous post')!==-1||txt==='‹')prevLink=a.href;if(txt.indexOf('newer')!==-1||txt.indexOf('next post')!==-1||txt==='›')nextLink=a.href;});
    if(olderEl)prevLink=olderEl.href;if(newerEl)nextLink=newerEl.href;
    var indL=$id('swipe-left-ind'),indR=$id('swipe-right-ind');
    var swipeStart=null,swipeActive=false;
    if(prevLink||nextLink){
      document.addEventListener('touchstart',function(e){if(e.touches.length!==1)return;var panels=qsa('#s803-search-panel.show,#s803-scores-panel.show,#s803-excl-panel.show,#s803-bkm-panel.show,#s803-pin-screen.show,#s803-action-sheet.show');if(panels.length)return;swipeStart={x:e.touches[0].clientX,y:e.touches[0].clientY};swipeActive=true;},{passive:true});
      document.addEventListener('touchmove',function(e){if(!swipeActive||!swipeStart)return;var dx=e.touches[0].clientX-swipeStart.x,dy=Math.abs(e.touches[0].clientY-swipeStart.y);if(dy>30){swipeActive=false;return;}if(Math.abs(dx)>20){if(dx<0&&nextLink&&indL){indL.classList.add('visible');if(indR)indR.classList.remove('visible');}if(dx>0&&prevLink&&indR){indR.classList.add('visible');if(indL)indL.classList.remove('visible');}}},{passive:true});
      document.addEventListener('touchend',function(e){if(!swipeActive||!swipeStart)return;var dx=e.changedTouches[0].clientX-swipeStart.x,dy=Math.abs(e.changedTouches[0].clientY-swipeStart.y);swipeActive=false;if(indL)indL.classList.remove('visible');if(indR)indR.classList.remove('visible');if(dy>50||Math.abs(dx)<60){swipeStart=null;return;}var target=null;if(dx<0&&nextLink)target=nextLink;if(dx>0&&prevLink)target=prevLink;if(target){haptic('medium');var wrapper=qs('#s803-post-wrapper,article,.post-body');if(wrapper){wrapper.style.transition='transform 0.3s ease,opacity 0.3s ease';wrapper.style.transform=dx<0?'translateX(-110%)':'translateX(110%)';wrapper.style.opacity='0';}appToast(dx<0?'→ Next post':'← Previous post','#e03030');setTimeout(function(){window.location.href=target;},280);}swipeStart=null;},{passive:true});
    }
  }

  /* — EXCLUSIVE SECTION — */
  if(SA){
    var pinScreen=$id('s803-pin-screen'),exclPanel=$id('s803-excl-panel');
    var pinDots=$id('pin-dots'),pinErr=$id('pin-err');
    var exclFeed=$id('excl-feed'),exclBdg=$id('excl-bdg');
    var pinEntry='',exclLoaded=false;
    function updPD(){for(var i=0;i<4;i++){var dot=$id('pd'+i);if(dot){dot.classList.toggle('filled',i<pinEntry.length);dot.classList.remove('error');}}if(pinErr)pinErr.classList.remove('show');}
    function wrongPin(){haptic('error');for(var i=0;i<4;i++){var dot=$id('pd'+i);if(dot)dot.classList.add('error');}if(pinDots){pinDots.classList.add('shake');setTimeout(function(){pinDots.classList.remove('shake');},450);}if(pinErr)pinErr.classList.add('show');setTimeout(function(){pinEntry='';updPD();},600);}
    function checkPin(){if(pinEntry===VIP_PIN){haptic('success');localStorage.setItem('s803_excl_unlocked','1');pinScreen.classList.remove('show');openExclusive();}else wrongPin();}
    var keypad=$id('pin-keypad');if(keypad)keypad.addEventListener('click',function(e){var btn=e.target.closest('.pin-key');if(!btn)return;var d=btn.dataset.d;if(d!==undefined&&pinEntry.length<4){haptic('light');pinEntry+=d;updPD();if(pinEntry.length===4)setTimeout(checkPin,120);}});
    var pinDel=$id('pin-del');if(pinDel)pinDel.addEventListener('click',function(){pinEntry=pinEntry.slice(0,-1);updPD();haptic('light');});
    var pinClose=$id('pin-close');if(pinClose)pinClose.addEventListener('click',function(){pinScreen.classList.remove('show');pinEntry='';updPD();});
    var exclLock=$id('excl-lock');if(exclLock)exclLock.addEventListener('click',function(){localStorage.removeItem('s803_excl_unlocked');exclPanel.classList.remove('show');pinEntry='';updPD();appToast('🔒 Section locked','#888');});
    var navExcl=$id('nav-excl');
    if(navExcl)navExcl.addEventListener('click',function(){closeAllPanels();navExcl.classList.add('active');if(exclBdg)exclBdg.classList.remove('show');haptic('light');if(localStorage.getItem('s803_excl_unlocked')==='1')openExclusive();else{pinEntry='';updPD();pinScreen.classList.add('show');}});
    function openExclusive(){exclPanel.classList.add('show');if(!exclLoaded)loadExclusivePosts();}
    function loadExclusivePosts(){exclLoaded=true;if(exclFeed)exclFeed.innerHTML='<div style="text-align:center;padding:48px"><div style="width:32px;height:32px;border:2px solid var(--s803-border);border-top-color:var(--s803-gold);border-radius:50%;animation:ptrspin 0.7s linear infinite;display:inline-block"></div></div>';var old=$id('s803-excl-script');if(old)old.remove();var s=document.createElement('script');s.id='s803-excl-script';s.src=SITE_URL+'/feeds/posts/default/-/'+encodeURIComponent(VIP_LABEL)+'?max-results=20&orderby=updated&alt=json&callback=s803ExclCB';s.onerror=function(){if(exclFeed)exclFeed.innerHTML='<div class="excl-empty"><span>⚠️</span>Could not load posts.</div>';};document.head.appendChild(s);}
    window.s803ExclCB=function(data){if(!exclFeed)return;var entries=(data.feed&&data.feed.entry)?data.feed.entry:[];if(!entries.length){exclFeed.innerHTML='<div class="excl-empty"><span>🌟</span>No exclusive posts yet.<br/>Add posts with the <b>'+VIP_LABEL+'</b> label.</div>';return;}var html='';entries.forEach(function(entry){var title=entry.title?entry.title['$t']:'Untitled',link='';if(entry.link)entry.link.forEach(function(l){if(l.rel==='alternate')link=l.href;});var date='';try{date=new Date(entry.published['$t']).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}catch(e){}var thumb=null;if(entry.media$thumbnail&&entry.media$thumbnail.url)thumb=entry.media$thumbnail.url.replace('/s72-c/','/s400-c/');else if(entry.content&&entry.content['$t']){var m=entry.content['$t'].match(/src="([^"]+\.(jpg|jpeg|png|webp)[^"]*)"/i);if(m)thumb=m[1];}var thumbHtml=thumb?'<img class="excl-card-thumb" src="'+thumb+'" alt="" loading="lazy" onerror="this.style.display=\'none\'">':'<div class="excl-card-thumb-placeholder">🌟</div>';html+='<a class="excl-card" href="'+link+'">'+thumbHtml+'<div class="excl-card-body"><div class="excl-badge">🌟 Exclusive</div><div class="excl-card-title">'+title+'</div><div class="excl-card-date">'+date+'</div></div></a>';});exclFeed.innerHTML=html;};
    window.addEventListener('popstate',function(){if(exclPanel)exclPanel.classList.remove('show');if(pinScreen)pinScreen.classList.remove('show');});
  }

  /* — VOICE SEARCH — */
  var voiceBtn=$id('s803-voice-btn'),recognition=null;
  var SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(voiceBtn){
    if(!SpeechRecognition)voiceBtn.style.display='none';
