  function doSearch(q){if(!q||q.length<2){showSearchPrompt();return;}if(q===lastQuery)return;lastQuery=q;addRecentSearch(q);trackSearch(q);if(searchRes)searchRes.innerHTML='<div style="text-align:center;padding:32px"><div style="width:28px;height:28px;border:2px solid var(--s803-border);border-top-color:var(--s803-accent);border-radius:50%;animation:ptrspin 0.7s linear infinite;display:inline-block"></div></div>';var old=$id('s803-search-script');if(old)old.remove();var s=document.createElement('script');s.id='s803-search-script';s.src=SITE_URL+'/feeds/posts/default?q='+encodeURIComponent(q)+'&max-results=12&orderby=published&alt=json&callback=s803SearchCB';s.onerror=function(){if(searchRes)searchRes.innerHTML='<div class="s803-sr-msg"><span>⚠️</span>Could not reach the server.</div>';};document.head.appendChild(s);}
