  (function injectAds(){
    var pubId = _c.adsense_id || 'ca-pub-5622139873916803';
    if(!pubId) return;

    if(_c.adsense_auto){
      var as = document.createElement('script');
      as.async = true; as.crossOrigin = 'anonymous';
      as.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+pubId;
      document.head.appendChild(as);
      var ini = document.createElement('script');
      ini.textContent = '(adsbygoogle=window.adsbygoogle||[]).push({google_ad_client:"'+pubId+'",enable_page_level_ads:true});';
      document.head.appendChild(ini);
      return;
    }

    function mkAd(slotId, format, fullW){
      if(!slotId) return null;
      var wrap = document.createElement('div');
      wrap.style.cssText = 'text-align:center;overflow:hidden;padding:6px 0';
      wrap.innerHTML = '<ins class="adsbygoogle"'
        +' style="display:block'+(fullW?';width:100%':'')+'"'
        +' data-ad-client="'+pubId+'"'
        +' data-ad-slot="'+slotId+'"'
        +' data-ad-format="'+format+'"'
        +' data-full-width-responsive="true"></ins>';
      return wrap;
    }
    function pushAd(el){ if(el && window.adsbygoogle)(window.adsbygoogle=window.adsbygoogle||[]).push({}); }

    if(!document.querySelector('script[src*="adsbygoogle"]')){
      var sc = document.createElement('script');
      sc.async = true; sc.crossOrigin = 'anonymous';
      sc.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+pubId;
      document.head.appendChild(sc);
    }

    document.addEventListener('DOMContentLoaded', function(){
      if(_c.ad_top && _c.ad_slot_top){
        var topAd = mkAd(_c.ad_slot_top, 'auto', true);
        var ticker = document.getElementById('s803-ticker');
        var ref = ticker ? ticker.nextSibling : (document.body.firstChild);
        document.body.insertBefore(topAd, ref);
        pushAd(topAd);
      }

      if(_c.ad_infeed && _c.ad_slot_infeed){
        var posts = document.querySelectorAll('.blog-post,.post-outer,article.post,hentry,.item-post');
        posts.forEach(function(post, i){
          if((i+1) % 4 === 0){
            var inFeedAd = mkAd(_c.ad_slot_infeed, 'fluid', true);
            if(inFeedAd && post.parentNode) post.parentNode.insertBefore(inFeedAd, post.nextSibling);
            pushAd(inFeedAd);
          }
        });
      }

      if(_c.ad_article && _c.ad_slot_article){
        var bodies = document.querySelectorAll('.post-body,.entry-content,[itemprop="articleBody"]');
        bodies.forEach(function(body){
          var paras = body.querySelectorAll('p');
          var ins = paras[2] || paras[paras.length-1];
          if(ins){
            var artAd = mkAd(_c.ad_slot_article, 'fluid', true);
            if(artAd && ins.parentNode) ins.parentNode.insertBefore(artAd, ins.nextSibling);
            pushAd(artAd);
          }
        });
      }

      if(_c.ad_sticky && _c.ad_slot_sticky){
        if(_c.ad_free_vip && localStorage.getItem('s803_excl_unlocked') === '1') return;
        var stickyWrap = document.createElement('div');
        stickyWrap.style.cssText = 'position:fixed;bottom:var(--s803-nav-h,62px);left:0;right:0;z-index:9980;background:rgba(8,8,8,0.9);backdrop-filter:blur(8px);border-top:1px solid rgba(255,255,255,0.06);text-align:center;';
        var stickyAd = mkAd(_c.ad_slot_sticky, 'banner', true);
        if(stickyAd){ stickyWrap.appendChild(stickyAd); document.body.appendChild(stickyWrap); pushAd(stickyAd); }
      }

      if(_c.ad_custom){
        var customWrap = document.createElement('div');
        customWrap.style.cssText = 'width:100%;overflow:hidden;text-align:center;padding:4px 0';
        customWrap.innerHTML = _c.ad_custom;
        var tickerEl = document.getElementById('s803-ticker');
        if(tickerEl && tickerEl.nextSibling) document.body.insertBefore(customWrap, tickerEl.nextSibling);
        else document.body.insertBefore(customWrap, document.body.firstChild);
      }
    });
  })();

})();
