/* ═══ LIVE TV SYSTEM ═══ */
(function(){
  /* ── Storage key ── */
  var LTV_KEY   = 's803_livetv_channels_v2';
  var ADMIN_PIN = (window.S803_CFG && window.S803_CFG.VIP_PIN) || '8033';
  var LTV_FB    = 'https://sports-803-1b806-default-rtdb.firebaseio.com/livetv/channels.json';

  /* ── Firebase: fetch all channels (all users) ── */
  function ltvFetch(cb) {
    rtdb.ref('livetv/channels').once('value').then(function(snapshot) {
      var data = snapshot.val();
      var arr = [];
      if (data && typeof data === 'object') {
        Object.keys(data).forEach(function(k){ arr.push(Object.assign({_key:k}, data[k])); });
      }
      cb(arr);
    }).catch(function(){ cb([]); });
  }

  /* ── Firebase: push new channel ── */
  function ltvPush(ch, cb) {
    rtdb.ref('livetv/channels').push(ch)
      .then(function(){ if(cb) cb(); })
      .catch(function(){ alert('Error saving to Firebase — check your database rules.'); });
  }

  /* ── Firebase: delete channel by key ── */
  function ltvDelete(key, cb) {
    rtdb.ref('livetv/channels/' + key).remove()
      .then(function(){ if(cb) cb(); })
      .catch(function(){});
  }

  function ltvRender(){
    var container = document.getElementById('s803-livetv-channels');
    if(!container) return;
    container.innerHTML = '<div style="text-align:center;padding:20px;color:rgba(255,255,255,0.4);font-size:13px;">Loading channels...</div>';
    ltvFetch(function(channels){
      if(!channels.length){
        container.innerHTML = '<div class="s803-livetv-empty">📺 No channels yet.<br/>Admin can add channels below.</div>';
      } else {
        var html = '';
        channels.forEach(function(ch, idx){
          var logoHtml = ch.logo
            ? '<img class="s803-livetv-logo" src="' + escHtml(ch.logo) + '" alt="" onerror="this.style.display=\'none\';this.nextSibling.style.display=\'flex\'">'
              + '<div class="s803-livetv-logo-placeholder" style="display:none">' + escHtml((ch.name||'TV').substring(0,2).toUpperCase()) + '</div>'
            : '<div class="s803-livetv-logo-placeholder">' + escHtml((ch.name||'TV').substring(0,2).toUpperCase()) + '</div>';
          var key = ch._key || idx;
          html += '<div class="s803-livetv-card" onclick="s803LTVWatch(\'' + escHtml(ch.url) + '\',\'' + escHtml(ch.name) + '\')">'
            + logoHtml
            + '<div class="s803-livetv-info"><div class="s803-livetv-name">' + escHtml(ch.name) + '</div>'
            + '<span class="s803-livetv-badge">LIVE</span></div>'
            + '<button class="s803-livetv-watch" onclick="event.stopPropagation();s803LTVWatch(\'' + escHtml(ch.url) + '\',\'' + escHtml(ch.name) + '\')">Watch</button>'
            + '<button class="s803-livetv-share" title="Copy link" onclick="event.stopPropagation();s803ShareChannel(\'' + escHtml(String(key)) + '\',\'' + escHtml(ch.name) + '\')">&#128203;</button>'
            + '</div>';
          if((idx+1) % 4 === 0){
            html += '<div class="s803-livetv-ad"><ins class="adsbygoogle" style="display:block;width:100%;height:100px;" data-ad-client="ca-pub-5622139873916803" data-ad-slot="auto" data-ad-format="rectangle" data-full-width-responsive="true"></ins></div>';
          }
        });
        container.innerHTML = html;
        container.querySelectorAll('.adsbygoogle').forEach(function(el){ try{(adsbygoogle=window.adsbygoogle||[]).push({});}catch(e){} });
      }
      /* Admin button */
      var adminBtn = document.createElement('button');
      adminBtn.className = 's803-livetv-admin-btn';
      adminBtn.textContent = '⚙️ Manage Channels (Admin)';
      adminBtn.onclick = ltvAdmin;
      container.appendChild(adminBtn);

      /* Also refresh homepage Live TV widget */
      renderLTVWidget();
    });
  }

  function escHtml(s){ return String(s||'').replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }

  /* ─────────────────────────────────────────────────────────────────────────
   * s803BuildProxyUrl(url)
   *
   * No auto-detection. You control routing by prefixing the URL you save
   * in Firebase with either:
   *
   *   mora=https://...   →  plays via ?mora=  (HLS / DASH / direct streams)
   *   embed=https://...  →  plays via ?embed= (domain-protected embed pages)
   *
   * If no prefix is present the raw URL is loaded directly in the iframe
   * with no proxy wrapper.
   *
   * Examples:
   *   mora=https://tv.sportsnews.id/p/ziggo1.html
   *   embed=https://v3.sportssonline.click/channels/hd/hd5.php
   *   https://example.com/stream.m3u8   ← no prefix, loaded as-is
   * ───────────────────────────────────────────────────────────────────────── */
  /* ─────────────────────────────────────────────────────────────────────────
   * s803BuildProxyUrl(rawValue)
   *
   * Mirrors the widget's buildProxyUrl exactly:
   *   mora=<url>   → PLAYER_BASE + ?mora=<url>   (raw — no encodeURIComponent)
   *   embed=<url>  → PLAYER_BASE + ?embed=<url>  (raw — no encodeURIComponent)
   *   https://...  → passed through directly (no proxy)
   *
   * WHY no encodeURIComponent:
   *   The media-player page reads location.search itself and must receive
   *   the raw URL string. Encoding breaks its own URL parser.
   *
   * Security: javascript: URLs are blocked. The iframe carries a full
   * sandbox attribute (allow-same-origin allow-scripts allow-popups
   * allow-forms allow-modals allow-presentation allow-downloads) which
   * limits what embedded content can do regardless of the URL.
   * ───────────────────────────────────────────────────────────────────────── */
  function s803BuildProxyUrl(url) {
    var PROXY_BASE = 'https://sports803.github.io/player/';

    if (!url) return '';

    var v = url.trim();

    /* Block javascript: protocol injection */
    if (/^javascript:/i.test(v)) return '';

    /* mora= prefix → raw pass through ?mora= */
    if (/^mora=/i.test(v)) {
      return PROXY_BASE + '?mora=' + v.slice(5).trim();   /* raw, no encode */
    }

    /* embed= prefix → raw pass through ?embed= */
    if (/^embed=/i.test(v)) {
      return PROXY_BASE + '?embed=' + v.slice(6).trim();  /* raw, no encode */
    }

    /* Plain URL — pass directly to iframe (no proxy) */
    return v;
  }
  window.s803LTVWatch = function(url, name){
    var player = document.getElementById('s803-livetv-player');
    var iframe  = document.getElementById('s803-livetv-iframe');
    var label   = document.getElementById('s803-livetv-player-label');
    if(!player || !iframe) return;

    /* Route the URL through the correct proxy parameter */
    var finalUrl = s803BuildProxyUrl(url);

    iframe.src = finalUrl;
    if(label) label.textContent = name || '';
    player.style.display = 'block';
    document.body.style.overflow = 'hidden';

    setTimeout(function(){
      var ad = document.createElement('ins');
      ad.className='adsbygoogle';
      ad.style.cssText='position:absolute;bottom:0;left:0;right:0;height:60px;display:block;z-index:100001;pointer-events:none;';
      ad.setAttribute('data-ad-client','ca-pub-5622139873916803');
      ad.setAttribute('data-ad-slot','auto');
      ad.setAttribute('data-ad-format','horizontal');
      player.appendChild(ad);
      try{(adsbygoogle=window.adsbygoogle||[]).push({});}catch(e){}
    }, 3000);
  };

  window.s803CloseTVPlayer = function(){
    var player = document.getElementById('s803-livetv-player');
    var iframe = document.getElementById('s803-livetv-iframe');
    if(iframe) iframe.src = '';
    if(player) player.style.display = 'none';
    document.body.style.overflow = '';
  };

  function ltvAdmin(){
    var pin = prompt('Enter admin PIN:');
    if(pin !== ADMIN_PIN){ if(pin!==null) alert('Wrong PIN'); return; }
    ltvAdminPanel();
  }

  function ltvAdminPanel(){
    var modal = document.createElement('div');
    modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.85);z-index:999999;overflow-y:auto;padding:16px;';
    var inner = document.createElement('div');
    inner.style.cssText = 'max-width:480px;margin:0 auto;background:#141414;border-radius:14px;padding:20px;';
    function buildForm(){
      ltvFetch(function(channels){
        var chList = channels.map(function(ch){
          var key = ch._key || '';
          return '<div style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.06);border-radius:8px;padding:10px;margin-bottom:8px;">'
            + '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:14px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escHtml(ch.name) + '</div>'
            + '<div style="font-size:11px;color:#888;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escHtml(ch.url) + '</div></div>'
            + '<button onclick="s803LTVDelete(\'' + escHtml(key) + '\')" style="background:#c00;border:none;color:#fff;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:13px;">Delete</button></div>';
        }).join('');
        inner.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">'
          + '<div style="font-size:18px;font-weight:800;color:#fff;">📺 Manage Live TV (Global)</div>'
          + '<button onclick="this.closest(\'[style*=fixed]\').remove();document.body.style.overflow=\'\';" style="background:rgba(255,255,255,0.1);border:none;color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:18px;">&#215;</button></div>'
          + '<div style="font-size:12px;color:#25d366;background:rgba(37,211,102,0.1);border-radius:6px;padding:6px 10px;margin-bottom:12px;">✅ Channels added here are visible to ALL users.</div>'
          + '<div style="font-size:13px;color:#888;margin-bottom:12px;">Add a new channel:</div>'
          + '<input id="ltv-inp-name" placeholder="Channel name (e.g. Sky Sports)" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:8px;padding:10px 12px;color:#fff;font-size:14px;margin-bottom:8px;" />'
          + '<input id="ltv-inp-logo" placeholder="Logo URL (optional)" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:8px;padding:10px 12px;color:#fff;font-size:14px;margin-bottom:8px;" />'
          + '<input id="ltv-inp-url" placeholder="Stream/embed URL" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:8px;padding:10px 12px;color:#fff;font-size:14px;margin-bottom:12px;" />'
          + '<button onclick="s803LTVAdd()" style="width:100%;padding:12px;background:#e03030;border:none;color:#fff;border-radius:10px;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:20px;">+ Add Channel</button>'
          + '<div style="font-size:13px;color:#888;margin-bottom:10px;">Current channels (' + channels.length + '):</div>'
          + chList;
      });
    }
    buildForm();
    modal.appendChild(inner);
    document.body.appendChild(modal);
    document.body.style.overflow = 'hidden';
    window._ltvModal = modal;
    window._ltvBuildForm = function(){ buildForm(); };
  }

  window.s803LTVAdd = function(){
    var name = (document.getElementById('ltv-inp-name')||{}).value||'';
    var logo = (document.getElementById('ltv-inp-logo')||{}).value||'';
    var url  = (document.getElementById('ltv-inp-url')||{}).value||'';
    if(!name.trim()||!url.trim()){ alert('Name and URL are required'); return; }
    var btn = document.querySelector('[onclick="s803LTVAdd()"]');
    if(btn){ btn.textContent = 'Saving...'; btn.disabled = true; }
    ltvPush({ name:name.trim(), logo:logo.trim(), url:url.trim() }, function(){
      ltvRender();
      if(window._ltvBuildForm) window._ltvBuildForm();
      alert('Channel "' + name.trim() + '" added! All users will now see it.');
    });
  };

  window.s803LTVDelete = function(key){
    if(!confirm('Delete this channel for ALL users?')) return;
    ltvDelete(key, function(){
      ltvRender();
      if(window._ltvBuildForm) window._ltvBuildForm();
    });
  };

  /* Open/close Live TV panel */
  window.s803OpenLiveTV = function(){
    var p  = document.getElementById('s803-livetv-panel');
    var bd = document.getElementById('s803-livetv-backdrop');
    if(!p) return;
    /* close other panels first */
    if(typeof s803CloseYou==='function') s803CloseYou();
    if(typeof s803CloseSports==='function') s803CloseSports();
    ltvRender();
    p.classList.add('show');
    if(bd) bd.classList.add('show');
    document.body.style.overflow = 'hidden';
  };
  /* ── Share channel: copy ?channel=KEY link to clipboard ── */
  window.s803ShareChannel = function(key, name) {
    var baseUrl  = window.location.origin + window.location.pathname;
    var shareUrl = baseUrl + '?channel=' + encodeURIComponent(key);
    if (navigator.clipboard) {
      navigator.clipboard.writeText(shareUrl).then(function() {
        s803Toast('Link copied! Share it to watch ' + name + '.');
      }).catch(function() {
        s803ShareFallback(shareUrl);
      });
    } else {
      s803ShareFallback(shareUrl);
    }
  };
  function s803ShareFallback(url) {
    var ta = document.createElement('textarea');
    ta.value = url;
    ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch(e) {}
    document.body.removeChild(ta);
    s803Toast('Link copied!');
  }
  function s803Toast(msg) {
    /* Use existing toast if available, else simple alert */
    if (typeof s803ShowToast === 'function') { s803ShowToast(msg); return; }
    var wrap = document.getElementById('s803-toast-wrap');
    if (wrap) {
      var t = document.createElement('div');
      t.style.cssText = 'background:rgba(30,30,30,0.95);color:#fff;padding:10px 16px;border-radius:20px;font-size:13px;font-weight:600;box-shadow:0 4px 16px rgba(0,0,0,0.5);pointer-events:none;';
      t.textContent = msg;
      wrap.appendChild(t);
      setTimeout(function(){ if(t.parentNode) t.parentNode.removeChild(t); }, 3000);
    } else {
      alert(msg);
    }
  }

  /* ── Auto-play channel from ?channel= URL parameter ── */
  (function() {
    var params = new URLSearchParams(window.location.search);
    var channelKey = params.get('channel');
    if (!channelKey) return;
    function tryOpenChannel() {
      if (typeof rtdb === 'undefined') { setTimeout(tryOpenChannel, 200); return; }
      rtdb.ref('livetv/channels/' + channelKey).once('value')
        .then(function(snapshot) {
          var ch = snapshot.val();
          if (ch && ch.url) {
            /* Open the Live TV panel first so the player context is ready */
            if (typeof s803OpenLiveTV === 'function') s803OpenLiveTV();
            /* Small delay to let the panel render, then auto-watch */
            setTimeout(function() {
              if (typeof s803LTVWatch === 'function') {
                s803LTVWatch(ch.url, ch.name || 'Live Channel');
              }
            }, 300);
            /* Clean URL so refresh doesn't replay */
            var cleanUrl = window.location.origin + window.location.pathname;
            window.history.replaceState({}, '', cleanUrl);
          }
        })
        .catch(function() { console.warn('Channel not found:', channelKey); });
    }
    if (document.readyState !== 'loading') {
      /* Wait a moment for Firebase to init */
      setTimeout(tryOpenChannel, 600);
    } else {
      document.addEventListener('DOMContentLoaded', function() {
        setTimeout(tryOpenChannel, 600);
      });
    }
  })();

  window.s803CloseLiveTV = function(){
    var p  = document.getElementById('s803-livetv-panel');
    var bd = document.getElementById('s803-livetv-backdrop');
    if(p)  p.classList.remove('show');
    if(bd) bd.classList.remove('show');
    document.body.style.overflow = '';
  };

  document.addEventListener('DOMContentLoaded', function(){
    /* Render channels on first open */
  });
})();
