(function(){
  'use strict';

  /* ── Backddrops ── */
  function _bd(id, fn){
    var el = document.getElementById(id);
    if(el) el.addEventListener('click', fn);
  }
  _bd('s803-you-backdrop',    s803CloseYou);
  _bd('s803-sports-backdrop', s803CloseSports);
  _bd('s803-livetv-backdrop', function(){ if(typeof s803CloseLiveTV==='function') s803CloseLiveTV(); });

  /* ── Nav click ── */
  window.s803NavClick = function(btn, tab){
    if(navigator.vibrate) navigator.vibrate(10);

    if(tab === 'home'){
      s803CloseYou(); s803CloseSports();
      _setActive(btn);
      /* Close any open panels */
      if(typeof closeAllPanels === 'function') closeAllPanels();
      /* If we're on a post page, go to home */
      var isHome = /^\/?$|\/index\.html$/.test(window.location.pathname);
      if(!isHome){
        var su = (window.S803_CFG && window.S803_CFG.SITE_URL) || 'https://sports803livestream.blogspot.com';
        window.location.href = su;
      }
      return;
    }

    if(tab === 'live'){
      s803CloseYou(); s803CloseSports(); if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      /* Delegate to existing scores button */
      var nb = document.getElementById('nav-scores');
      if(nb) nb.click();
      return;
    }

    if(tab === 'livetv'){
      s803CloseYou(); s803CloseSports();
      _setActive(btn);
      if(typeof s803OpenLiveTV === 'function') s803OpenLiveTV();
      return;
    }

    if(tab === 'sports'){
      s803CloseYou();
      _setActive(btn);
      _openSports();
      return;
    }

    if(tab === 'search'){
      s803CloseYou(); s803CloseSports();
      _setActive(btn);
      if(typeof window.openSearch === 'function') window.openSearch();
      else {
        var sb = document.getElementById('s803-search-btn');
        if(sb) sb.click();
      }
      return;
    }

    if(tab === 'you'){
      s803CloseSports();
      _setActive(btn);
      _openYou();
      return;
    }
  };

  function _setActive(btn){
    document.querySelectorAll('.s803-nav-btn').forEach(function(b){ b.classList.remove('active'); });
    if(btn) btn.classList.add('active');
  }

  /* ── Auto-active on load ── */
  document.addEventListener('DOMContentLoaded', function(){
    var path = window.location.pathname + window.location.search;
    var isLive = /\/search\/label\/Live/i.test(path);
    _setActive(document.getElementById(isLive ? 'nav-live' : 'nav-home'));
    _initYou();
    _buildSports();
  });

  /* ══ YOU PANEL ══ */
  function _openYou(){
    var p = document.getElementById('s803-you-panel');
    var bd = document.getElementById('s803-you-backdrop');
    if(!p) return;
    _refreshYouStats();
    p.classList.add('show');
    if(bd) bd.classList.add('show');
    document.body.style.overflow = 'hidden';
  }

  window.s803CloseYou = function(){
    var p  = document.getElementById('s803-you-panel');
    var bd = document.getElementById('s803-you-backdrop');
    if(p)  p.classList.remove('show');
    if(bd) bd.classList.remove('show');
    document.body.style.overflow = '';
  };

  function _initYou(){
    /* PWA badge */
    var isPWA = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
    var pwaTag = document.getElementById('you-pwa-tag');
    if(pwaTag && isPWA) pwaTag.style.display = '';

    /* Device info */
    var ua = navigator.userAgent;
    var dev = /Android/i.test(ua) ? 'Android' : (/iPad|iPhone|iPod/.test(ua) ? 'iOS' : 'Desktop');
    var sub = document.getElementById('you-device-info');
    if(sub) sub.textContent = dev + (isPWA ? ' · Installed' : ' · Browser');

    /* Install row */
    if(!isPWA){
      var ir = document.getElementById('you-install-row');
      if(ir){
        ir.style.display = '';
        ir.addEventListener('click', function(e){
          e.preventDefault();
          if(window._s803DeferredPrompt) window._s803DeferredPrompt.prompt();
          else {
            var su = (window.S803_CFG && window.S803_CFG.SITE_URL) || 'https://sports803livestream.blogspot.com';
            window.location.href = su + '?install=1';
          }
        });
      }
    }

    /* Saved posts → open bookmarks panel */
    var goSaved = document.getElementById('you-go-saved');
    if(goSaved) goSaved.addEventListener('click', function(e){
      e.preventDefault();
      s803CloseYou();
      setTimeout(function(){
        var nb = document.getElementById('nav-bkm');
        if(nb) nb.click();
      }, 220);
    });

    /* Alerts */
    var goAlerts = document.getElementById('you-go-alerts');
    if(goAlerts) goAlerts.addEventListener('click', function(e){
      e.preventDefault();
      s803CloseYou();
      setTimeout(function(){
        var bell = document.getElementById('nav-bell');
        if(bell) bell.click();
      }, 220);
    });

    /* Theme */
    var goTheme = document.getElementById('you-go-theme');
    if(goTheme) goTheme.addEventListener('click', function(e){
      e.preventDefault();
      s803CloseYou();
      setTimeout(function(){
        var tb = document.getElementById('s803-theme-btn');
        if(tb) tb.click();
      }, 220);
    });

    /* Stat row: saved → open bookmarks */
    var statSaved = document.getElementById('you-stat-saved-wrap');
    if(statSaved) statSaved.addEventListener('click', function(){
      s803CloseYou();
      setTimeout(function(){
        var nb = document.getElementById('nav-bkm');
        if(nb) nb.click();
      }, 220);
    });

    /* Fav teams */
    var favBtn = document.getElementById('you-fav-teams-btn');
    if(favBtn) favBtn.addEventListener('click', function(e){
      e.preventDefault();
      var sec  = document.getElementById('you-fav-teams-section');
      var list = document.getElementById('you-fav-teams-list');
      if(!sec || !list) return;
      if(sec.style.display !== 'none'){ sec.style.display = 'none'; return; }
      sec.style.display = '';
      var favs = [];
      try { favs = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]'); } catch(e){}
      list.innerHTML = favs.length ? favs.map(function(t){
        return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--s803-border,#222)">'
          +'<span style="font-size:16px">&#11088;</span>'
          +'<span style="flex:1;font-size:13px;font-weight:600;color:var(--s803-text,#f0ede8)">'+t+'</span>'
          +'<button onclick="s803YouRemoveFav(\''+t+'\')" style="background:none;border:none;color:var(--s803-accent,#e03030);font-size:11px;cursor:pointer;padding:2px 6px">Remove</button>'
          +'</div>';
      }).join('')
      : '<div style="color:var(--s803-muted,#787470);font-size:12px;padding:8px 0">No teams yet. Star teams in the Scores tab.</div>';
    });

    _refreshYouStats();
  }

  window.s803YouRemoveFav = function(name){
    var favs = [];
    try { favs = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]'); } catch(e){}
    favs = favs.filter(function(t){ return t !== name; });
    localStorage.setItem('s803_fav_teams', JSON.stringify(favs));
    var sec = document.getElementById('you-fav-teams-section');
    if(sec) sec.style.display = 'none';
    var fb = document.getElementById('you-fav-teams-btn');
    if(fb) fb.click();
    _refreshYouStats();
    if(window.appToast) window.appToast('Removed from My Teams', '#888');
  };

  function _refreshYouStats(){
    var saved = 0, sessions = 0, teams = 0;
    try { saved    = JSON.parse(localStorage.getItem('s803_bkm') || '[]').length; } catch(e){}
    try { sessions = parseInt(localStorage.getItem('s803_sessions') || '0'); } catch(e){}
    try { teams    = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]').length; } catch(e){}

    var es = document.getElementById('you-stat-saved');
    var en = document.getElementById('you-stat-sessions');
    var et = document.getElementById('you-stat-teams');
    if(es) es.textContent = saved;
    if(en) en.textContent = sessions;
    if(et) et.textContent = teams;

    var badge = document.getElementById('you-saved-badge');
    if(badge){ badge.textContent = saved; badge.style.display = saved > 0 ? '' : 'none'; }
  }

  /* ══ SPORTS PANEL ══ */
  var SPORTS = [
    {emoji:'&#127988;&#917607;&#917602;&#917605;&#917614;&#917607;&#917631;', name:'EPL',      label:'EPL'},
    {emoji:'&#11088;',  name:'UCL',      label:'champions league'},
