  ];

  function _buildSports(){
    var c = document.getElementById('sports-grid-panel');
    if(!c || c.dataset.built) return;
    c.dataset.built = '1';
    var su = (window.S803_CFG && window.S803_CFG.SITE_URL) || 'https://sports803livestream.blogspot.com';
    SPORTS.forEach(function(s){
      var a = document.createElement('a');
      a.className = 'sports-grid-item';
      a.href = su + '/search/label/' + encodeURIComponent(s.label);
      a.innerHTML = '<span class="sports-grid-emoji">'+s.emoji+'</span><span class="sports-grid-name">'+s.name+'</span>';
      c.appendChild(a);
    });
  }

  function _openSports(){
    var p  = document.getElementById('s803-sports-panel');
    var bd = document.getElementById('s803-sports-backdrop');
    if(!p) return;
    _buildSports();
    p.classList.add('show');
    if(bd) bd.classList.add('show');
    document.body.style.overflow = 'hidden';
  }

  window.s803CloseSports = function(){
    var p  = document.getElementById('s803-sports-panel');
    var bd = document.getElementById('s803-sports-backdrop');
    if(p)  p.classList.remove('show');
    if(bd) bd.classList.remove('show');
    document.body.style.overflow = '';
  };

  /* ── Wrap existing closeAllPanels so our panels also close ── */
  var _origClose = window.closeAllPanels;
  window.closeAllPanels = function(){
    s803CloseYou();
    s803CloseSports();
    if(typeof _origClose === 'function') _origClose();
  };

  /* ── Wrap updateBkmBadge to keep You panel in sync ── */
  var _origBkm = window.updateBkmBadge;
  window.updateBkmBadge = function(){
    if(typeof _origBkm === 'function') _origBkm();
    _refreshYouStats();
  };

  /* ── Escape closes panels ── */
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape'){ s803CloseYou(); s803CloseSports(); }
  });

  /* ── Control Panel nav_items override ── */
  /* Maps old nav IDs to new tab buttons */
  var REMAP = { home:'nav-home', live:'nav-live', scores:'nav-live', bkm:'nav-you', bell:'nav-you', saved:'nav-you', alerts:'nav-you' };
  document.addEventListener('DOMContentLoaded', function(){
    var _c = window.S803_CFG || {};
    if(_c.nav_items && _c.nav_items.length){
      _c.nav_items.forEach(function(item){
        var mappedId = REMAP[item.id || ''] || ('nav-' + (item.id || ''));
        var el = document.getElementById(mappedId);
        if(!el) return;
        var lbl = el.querySelector('.s803-nav-label');
        if(lbl && item.label) lbl.textContent = item.label;
      });
    }
  });

})();
