(function () {
  'use strict';

  function $id(id) { return document.getElementById(id); }
  function _bd(id, fn) { var el = $id(id); if (el) el.addEventListener('click', fn); }

  /* backdrops */
  _bd('s803-you-backdrop',    function () { s803CloseYou(); });
  _bd('s803-sports-backdrop', function () { s803CloseSports(); });
  _bd('s803-livetv-backdrop', function () { if(typeof s803CloseLiveTV==='function') s803CloseLiveTV(); });

  /* ── MAIN NAV DISPATCHER ── */
  window.s803NavClick = function (btn, tab) {
    if (navigator.vibrate) navigator.vibrate(10);

    if (tab === 'home') {
      s803CloseYou(); s803CloseSports();
      if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      if (typeof closeAllPanels === 'function') closeAllPanels();
      var isHome = window.location.pathname === '/' ||
                   /^\/?$|\/index\.html$/.test(window.location.pathname);
      if (!isHome) {
        var su = (window.S803_CFG && window.S803_CFG.SITE_URL) ||
                 'https://sports803livestream.blogspot.com';
        window.location.href = su;
      }
      return;
    }

    if (tab === 'live') {
      s803CloseYou(); s803CloseSports();
      if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      _openScores();
      return;
    }

    if (tab === 'livetv') {
      s803CloseYou(); s803CloseSports();
      _setActive(btn);
      if (typeof s803OpenLiveTV === 'function') { s803OpenLiveTV(); }
      return;
    }

    if (tab === 'sports') {
      s803CloseYou();
      if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      _openSports();
      return;
    }

    if (tab === 'search') {
      s803CloseYou(); s803CloseSports();
      if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      if (typeof window.openSearch === 'function') {
        window.openSearch();
      } else {
        var sb = $id('s803-search-btn');
        if (sb) sb.click();
      }
      return;
    }

    if (tab === 'you') {
      s803CloseSports();
      if(typeof s803CloseLiveTV==='function') s803CloseLiveTV();
      _setActive(btn);
      _openYou();
      return;
    }
  };

  function _setActive(btn) {
    document.querySelectorAll('.s803-nav-btn').forEach(function (b) {
      b.classList.remove('active');
    });
    if (btn) btn.classList.add('active');
  }

  /* ── LIVE / SCORES ── */
  function _openScores() {
    /* close any other overlay panels */
    ['s803-excl-panel','s803-bkm-panel','s803-search-panel'].forEach(function (id) {
      var el = $id(id); if (el) el.classList.remove('show');
    });
    document.querySelectorAll('.s803-nav-btn').forEach(function (b) {
      b.classList.remove('active');
    });
    document.getElementById('nav-live').classList.add('active');

    var scoresPanel = $id('s803-scores-panel');
    if (!scoresPanel) return;
    scoresPanel.classList.add('show');

    var mini = $id('s803-mini-score');
    if (mini) mini.classList.remove('show');

    var bdg = $id('scores-bdg');
    if (bdg) bdg.classList.remove('show');

    /* trigger a load if scores feed is empty */
    var feed = $id('scores-feed');
    if (feed && !feed.children.length) {
      /* click the first league pill to kick off a load */
      var firstPill = document.querySelector('.slp-pill.active') ||
                      document.querySelector('.slp-pill');
      if (firstPill) firstPill.click();
    }

    if (typeof gtag === 'function') {
      var league = (document.querySelector('.slp-pill.active') || {}).dataset;
      gtag('event', 'scores_panel_open', { league: league ? league.league : 'eng.1' });
    }
  }

  /* ── SPORTS PANEL ── */
  var SPORTS = [
    { emoji:'🏴󠁧󠁢󠁥󠁮󠁧󠁿', name:'EPL',        label:'Premier League' },
    { emoji:'⭐',   name:'UCL',        label:'champions league' },
    { emoji:'🇪🇸',   name:'La Liga',    label:'laliga' },
    { emoji:'🇮🇹',   name:'Serie A',    label:'serie a' },
    { emoji:'🇩🇪',   name:'Bundesliga', label:'bundesliga' },
    { emoji:'🇫🇷',   name:'Ligue 1',    label:'ligue 1' },
    { emoji:'🏎',   name:'Formula 1',  label:'F1' },
    { emoji:'🏍',   name:'MotoGP',     label:'MotoGP' },
    { emoji:'🏈',   name:'NFL',        label:'NFL' },
    { emoji:'🏀',   name:'NBA',        label:'NBA' },
    { emoji:'🏒',   name:'NHL',        label:'NHL' },
    { emoji:'🥊',   name:'UFC / MMA',  label:'ufc' },
    { emoji:'💪',   name:'WWE',        label:'wwe' },
    { emoji:'🎾',   name:'Tennis',     label:'tennis' },
    { emoji:'🏉',   name:'Rugby',      label:'Rugby' },
    { emoji:'🎬',   name:'Highlights', label:'highlights' },
    { emoji:'📰',   name:'News',       label:'News' },
    { emoji:'⚽',   name:'All Sports', label:'sports' }
  ];

  function _buildSports() {
    var c = $id('sports-grid-panel');
    if (!c || c.dataset.built) return;
    c.dataset.built = '1';
    var su = (window.S803_CFG && window.S803_CFG.SITE_URL) ||
             'https://sports803livestream.blogspot.com';
    SPORTS.forEach(function (s) {
      var a = document.createElement('a');
      a.className = 'sports-grid-item';
      a.href = su + '/search/label/' + encodeURIComponent(s.label);
      a.innerHTML = '<span class="sports-grid-emoji">' + s.emoji + '</span>'
                  + '<span class="sports-grid-name">'  + s.name  + '</span>';
      c.appendChild(a);
    });
  }

  function _openSports() {
    _buildSports();
    var p  = $id('s803-sports-panel');
    var bd = $id('s803-sports-backdrop');
    if (!p) return;
    p.classList.add('show');
    if (bd) bd.classList.add('show');
    document.body.style.overflow = 'hidden';
  }

  window.s803CloseSports = function () {
    var p  = $id('s803-sports-panel');
    var bd = $id('s803-sports-backdrop');
    if (p)  p.classList.remove('show');
    if (bd) bd.classList.remove('show');
    document.body.style.overflow = '';
  };

  /* ── YOU PANEL ── */
  function _openYou() {
    var p  = $id('s803-you-panel');
    var bd = $id('s803-you-backdrop');
    if (!p) return;
    _refreshYouStats();
    p.classList.add('show');
    if (bd) bd.classList.add('show');
    document.body.style.overflow = 'hidden';
  }

  window.s803CloseYou = function () {
    var p  = $id('s803-you-panel');
    var bd = $id('s803-you-backdrop');
    if (p)  p.classList.remove('show');
    if (bd) bd.classList.remove('show');
    document.body.style.overflow = '';
  };

  function _refreshYouStats() {
    var saved = 0, sessions = 0, teams = 0;
    try { saved    = JSON.parse(localStorage.getItem('s803_bkm')       || '[]').length; } catch (e) {}
    try { sessions = parseInt(localStorage.getItem('s803_sessions')    || '0');         } catch (e) {}
    try { teams    = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]').length; } catch (e) {}
    var es = $id('you-stat-saved');    if (es) es.textContent = saved;
    var en = $id('you-stat-sessions'); if (en) en.textContent = sessions;
    var et = $id('you-stat-teams');    if (et) et.textContent = teams;
    var badge = $id('you-saved-badge');
    if (badge) { badge.textContent = saved; badge.style.display = saved > 0 ? '' : 'none'; }
  }

  function _initYou() {
    var isPWA = window.matchMedia('(display-mode: standalone)').matches ||
                navigator.standalone === true;
    var pwaTag = $id('you-pwa-tag');
    if (pwaTag && isPWA) pwaTag.style.display = '';

    var ua  = navigator.userAgent;
    var dev = /Android/i.test(ua) ? 'Android'
            : (/iPad|iPhone|iPod/.test(ua) ? 'iOS' : 'Desktop');
    var sub = $id('you-device-info');
    if (sub) sub.textContent = dev + (isPWA ? ' · Installed' : ' · Browser');

    if (!isPWA) {
      var ir = $id('you-install-row');
      if (ir) {
        ir.style.display = '';
        ir.addEventListener('click', function (e) {
          e.preventDefault();
          if (window._s803DeferredPrompt) window._s803DeferredPrompt.prompt();
          else {
            var su = (window.S803_CFG && window.S803_CFG.SITE_URL) ||
                     'https://sports803livestream.blogspot.com';
            window.location.href = su + '?install=1';
          }
        });
      }
    }

    /* Saved Posts */
    var goSaved = $id('you-go-saved');
    if (goSaved) goSaved.addEventListener('click', function (e) {
      e.preventDefault();
      s803CloseYou();
      setTimeout(function () {
        var p = $id('s803-bkm-panel');
        if (p) {
          p.classList.add('show');
          if (typeof renderBookmarks === 'function') renderBookmarks();
        }
      }, 220);
    });

    /* Alerts */
    var goAlerts = $id('you-go-alerts');
    if (goAlerts) goAlerts.addEventListener('click', function (e) {
      e.preventDefault();
      s803CloseYou();
      setTimeout(function () {
        if (typeof doNotify === 'function') doNotify();
      }, 220);
    });

    /* Theme */
    var goTheme = $id('you-go-theme');
    if (goTheme) goTheme.addEventListener('click', function (e) {
      e.preventDefault();
      s803CloseYou();
      setTimeout(function () {
        var tb = $id('s803-theme-btn');
        if (tb) tb.click();
      }, 220);
    });

    /* stat saved row → bookmarks */
    var statSaved = $id('you-stat-saved-wrap');
    if (statSaved) statSaved.addEventListener('click', function () {
      s803CloseYou();
      setTimeout(function () {
        var p = $id('s803-bkm-panel');
        if (p) {
          p.classList.add('show');
          if (typeof renderBookmarks === 'function') renderBookmarks();
        }
      }, 220);
    });

    /* My Teams toggle */
    var favBtn = $id('you-fav-teams-btn');
    if (favBtn) favBtn.addEventListener('click', function (e) {
      e.preventDefault();
      var sec  = $id('you-fav-teams-section');
      var list = $id('you-fav-teams-list');
      if (!sec || !list) return;
      if (sec.style.display !== 'none') { sec.style.display = 'none'; return; }
      sec.style.display = '';
      var favs = [];
      try { favs = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]'); } catch (e) {}
      list.innerHTML = favs.length
        ? favs.map(function (t) {
            return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;'
              + 'border-bottom:1px solid var(--s803-border,#222)">'
              + '<span style="font-size:16px">⭐</span>'
              + '<span style="flex:1;font-size:13px;font-weight:600;'
              + 'color:var(--s803-text,#f0ede8)">' + t + '</span>'
              + '<button onclick="s803YouRemoveFav(\'' + t + '\')" '
              + 'style="background:none;border:none;color:var(--s803-accent,#e03030);'
              + 'font-size:11px;cursor:pointer;padding:2px 6px">Remove</button>'
              + '</div>';
          }).join('')
        : '<div style="color:var(--s803-muted,#787470);font-size:12px;padding:8px 0">'
          + 'No teams yet. Star teams in the Live tab.</div>';
    });

    _refreshYouStats();
  }

  window.s803YouRemoveFav = function (name) {
    var favs = [];
    try { favs = JSON.parse(localStorage.getItem('s803_fav_teams') || '[]'); } catch (e) {}
    favs = favs.filter(function (t) { return t !== name; });
    localStorage.setItem('s803_fav_teams', JSON.stringify(favs));
    var sec = $id('you-fav-teams-section');
    if (sec) sec.style.display = 'none';
    var fb  = $id('you-fav-teams-btn');
    if (fb) fb.click();
    _refreshYouStats();
    if (window.appToast) window.appToast('Removed from My Teams', '#888');
  };

  /* ── Wrap closeAllPanels ── */
  var _origClose = window.closeAllPanels;
  window.closeAllPanels = function () {
    s803CloseYou();
    s803CloseSports();
    var sp = $id('s803-scores-panel');
    if (sp) sp.classList.remove('show');
    if (typeof _origClose === 'function') _origClose();
  };

  /* ── Wrap updateBkmBadge ── */
  var _origBkm = window.updateBkmBadge;
  window.updateBkmBadge = function () {
    if (typeof _origBkm === 'function') _origBkm();
    _refreshYouStats();
  };

  /* ── Escape key ── */
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { s803CloseYou(); s803CloseSports(); }
  });

  /* ── Init on DOM ready ── */
  document.addEventListener('DOMContentLoaded', function () {
    /* mark correct nav button active */
    var path = window.location.pathname + window.location.search;
    var isLivePath = /\/search\/label\/Live/i.test(path);
    _setActive($id(isLivePath ? 'nav-live' : 'nav-home'));

    /* init panels */
    _initYou();
    _buildSports();
  });

})();
