(function(){
'use strict';
var $ = function(id){ return document.getElementById(id); };
var SITE = 'https://sports803livestream.blogspot.com';
var FB = 'https://sports-803-1b806-default-rtdb.firebaseio.com';
var ESPN = 'https://site.api.espn.com/apis/site/v2/sports';
var isPost = /\/\d{4}\/\d{2}\//.test(location.pathname);
var isHome = location.pathname === '/' || location.search.includes('m=1') || location.pathname === '/index.html';

/* ── HELPER: fetch JSON ───────────────────────────────────────── */
function getJSON(url, cb, fallback) {
  fetch(url).then(function(r){ return r.json(); }).then(cb).catch(function(){ if(fallback) fallback(); });
}

/* ══════════════════════════════════════════════════════════════════
   1. ESPN LIVE SCORES TICKER
══════════════════════════════════════════════════════════════════ */
var TICKER_FEEDS = [
  ESPN + '/soccer/eng.1/scoreboard',
  ESPN + '/soccer/uefa.champions/scoreboard',
  ESPN + '/basketball/nba/scoreboard'
];
function buildTicker() {
  var items = [];
  var done = 0;
  function tryBuild() {
    done++;
    if (done < TICKER_FEEDS.length) return;
    if (!items.length) return;
    var html = items.concat(items).map(function(i){ return i; }).join(''); // duplicate for seamless loop
    var inner = $('s803-ticker-inner');
    if (inner) { inner.innerHTML = html; }
    var el = $('s803-espn-ticker');
    if (el) el.style.display = 'flex';
  }
  TICKER_FEEDS.forEach(function(url){
    getJSON(url, function(data){
      var events = (data.events || []).slice(0, 5);
      events.forEach(function(ev){
        var comps = ev.competitions && ev.competitions[0];
        if (!comps) return;
        var teams = comps.competitors || [];
        var home = teams.find(function(t){ return t.homeAway === 'home'; }) || teams[0] || {};
        var away = teams.find(function(t){ return t.homeAway === 'away'; }) || teams[1] || {};
        var status = ev.status && ev.status.type;
        var isLive = status && status.state === 'in';
        var scoreH = (home.score !== undefined) ? home.score : '-';
        var scoreA = (away.score !== undefined) ? away.score : '-';
        var hName = (home.team && (home.team.abbreviation || home.team.shortDisplayName)) || '?';
        var aName = (away.team && (away.team.abbreviation || away.team.shortDisplayName)) || '?';
        var timeStr = isLive ? (status.detail || 'LIVE') : (ev.date ? new Date(ev.date).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '');
        items.push(
          '<span class="s803-tick-item">' +
          '<span>' + aName + '</span>' +
          '<span class="s803-tick-score">' + scoreA + ' - ' + scoreH + '</span>' +
          '<span>' + hName + '</span>' +
          (isLive ? '<span class="s803-tick-live">LIVE</span>' : '<span class="s803-tick-label">' + timeStr + '</span>') +
          '</span>'
        );
      });
      tryBuild();
    }, tryBuild);
  });
}
buildTicker();

/* ══════════════════════════════════════════════════════════════════
   2. WEEKLY SCHEDULE WIDGET (ESPN API — inject into homepage)
══════════════════════════════════════════════════════════════════ */
if (isHome) {
  var DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var weekEl = document.createElement('div');
  weekEl.id = 's803-weekly';
  weekEl.innerHTML = '<div class="s803-widget-header"><div class="s803-widget-title">📅 This Week</div></div>' +
    '<div class="s803-week-tabs" id="s803-week-tabs"></div>' +
    '<div id="s803-week-panels"></div>';
  var target = document.getElementById('s803-homepage-matches');
  if (target && target.parentNode) target.parentNode.insertBefore(weekEl, target.nextSibling);

  var today = new Date();
  var tabsEl = $('s803-week-tabs');
  var panelsEl = $('s803-week-panels');
  if (tabsEl && panelsEl) {
    for (var d = 0; d < 7; d++) {
      var dt = new Date(today); dt.setDate(today.getDate() + d - 1);
      var dayLabel = d === 1 ? 'Today' : DAYS[dt.getDay()];
      var tab = document.createElement('button');
      tab.className = 's803-week-tab' + (d === 1 ? ' active today' : '');
      tab.textContent = dayLabel;
      tab.setAttribute('data-day', d);
      tab.onclick = function(){
        document.querySelectorAll('.s803-week-tab').forEach(function(t){ t.classList.remove('active'); });
        this.classList.add('active');
        var idx = this.getAttribute('data-day');
        document.querySelectorAll('.s803-week-panel').forEach(function(p){ p.classList.remove('active'); });
        var panel = document.getElementById('s803-wp-' + idx);
        if (panel) panel.classList.add('active');
        if (panel && !panel.getAttribute('data-loaded')) loadDaySchedule(panel, idx);
      };
      tabsEl.appendChild(tab);

      var panel = document.createElement('div');
      panel.className = 's803-week-panel' + (d === 1 ? ' active' : '');
      panel.id = 's803-wp-' + d;
      panel.innerHTML = '<div class="s803-sched-empty">Loading...</div>';
      panelsEl.appendChild(panel);
    }
    // Load today panel immediately
    var todayPanel = $('s803-wp-1');
    if (todayPanel) loadDaySchedule(todayPanel, 1);
  }

  function loadDaySchedule(panel, dayOffset) {
    if (panel.getAttribute('data-loaded')) return;
    panel.setAttribute('data-loaded', '1');
    var dt = new Date(today); dt.setDate(today.getDate() + parseInt(dayOffset) - 1);
    var dateStr = dt.toISOString().slice(0,10).replace(/-/g,'');
    var feeds = [
      ESPN + '/soccer/eng.1/scoreboard?dates=' + dateStr,
      ESPN + '/soccer/uefa.champions/scoreboard?dates=' + dateStr,
      ESPN + '/basketball/nba/scoreboard?dates=' + dateStr
    ];
    var allEvents = [];
    var remaining = feeds.length;
    feeds.forEach(function(url){
      getJSON(url, function(data){
        (data.events || []).forEach(function(ev){ allEvents.push(ev); });
        remaining--;
        if (remaining === 0) renderDaySchedule(panel, allEvents);
      }, function(){ remaining--; if(remaining===0) renderDaySchedule(panel,allEvents); });
    });
  }

  function renderDaySchedule(panel, events) {
    if (!events.length) { panel.innerHTML = '<div class="s803-sched-empty">No matches scheduled</div>'; return; }
    var html = events.map(function(ev){
      var comps = ev.competitions && ev.competitions[0];
      var teams = (comps && comps.competitors) || [];
      var home = teams.find(function(t){return t.homeAway==='home';}) || teams[0] || {};
      var away = teams.find(function(t){return t.homeAway==='away';}) || teams[1] || {};
      var hName = (home.team && home.team.shortDisplayName) || '?';
      var aName = (away.team && away.team.shortDisplayName) || '?';
      var status = ev.status && ev.status.type;
      var isLive = status && status.state === 'in';
      var timeStr = isLive ? 'LIVE' : (ev.date ? new Date(ev.date).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '--:--');
      var league = (ev.season && ev.season.slug) || '';
      return '<div class="s803-sched-item">' +
        '<div class="s803-sched-teams">' +
        (isLive ? '<span class="s803-sched-live-dot"></span>' : '') +
        '<div><div class="s803-sched-vs">' + aName + ' vs ' + hName + '</div>' +
        '<div class="s803-sched-league">' + league.replace(/\./g,' ').toUpperCase() + '</div></div>' +
        '</div>' +
        '<div class="s803-sched-time">' + timeStr + '</div>' +
        '</div>';
    }).join('');
    panel.innerHTML = html;
  }
}

/* ══════════════════════════════════════════════════════════════════
   3. ON RIGHT NOW — fetch recent "Live" label posts
══════════════════════════════════════════════════════════════════ */
if (isHome) {
  var nowEl = $('s803-on-now');
  if (nowEl) {
    getJSON(SITE + '/feeds/posts/default/-/Live?max-results=3&orderby=published&alt=json', function(data){
      var entries = (data.feed && data.feed.entry) || [];
      // Filter posts published in last 4 hours
      var cutoff = Date.now() - 4 * 3600 * 1000;
      var live = entries.filter(function(e){
        var pub = new Date(e.published && e.published.$t).getTime();
        return pub > cutoff;
      });
      if (!live.length) return;
      var post = live[0];
      var title = post.title && post.title.$t || 'Live Match';
      var link = ((post.link || []).find(function(l){ return l.rel === 'alternate'; }) || {}).href || SITE;
      nowEl.style.display = 'block';
      nowEl.innerHTML = '<a class="s803-on-now-card" href="' + link + '">' +
        '<div class="s803-on-now-pulse"></div>' +
        '<div class="s803-on-now-text">' +
        '<div class="s803-on-now-label">🔴 Streaming Now</div>' +
        '<div class="s803-on-now-title">' + title + '</div>' +
        '</div>' +
        '<div class="s803-on-now-arrow">▶</div>' +
        '</a>';
    }, null);
  }
}

/* ══════════════════════════════════════════════════════════════════
   4. WATCH HISTORY STRIP — surface localStorage history
══════════════════════════════════════════════════════════════════ */
if (isHome) {
  try {
    var hist = JSON.parse(localStorage.getItem('s803_watch_history') || '[]');
    if (hist.length > 0) {
      var stripEl = document.createElement('div');
      stripEl.id = 's803-history-strip';
      var histHtml = '<div class="s803-hist-header">' +
        '<div class="s803-hist-title">▶ Continue Watching</div>' +
        '<span class="s803-hist-clear" id="s803-hist-clear">Clear</span>' +
        '</div>' +
        '<div class="s803-hist-scroll">' +
        hist.slice(0,6).map(function(item){
          return '<a class="s803-hist-card" href="' + (item.url||'#') + '">' +
            (item.thumb ? '<img class="s803-hist-thumb" src="' + item.thumb + '" alt="" loading="lazy"/>' : '<div class="s803-hist-thumb" style="display:flex;align-items:center;justify-content:center;font-size:28px">▶</div>') +
            '<div class="s803-hist-info">' +
            '<div class="s803-hist-name">' + (item.title||'Match') + '</div>' +
            '<div class="s803-hist-time">' + (item.time||'') + '</div>' +
            '</div></a>';
        }).join('') +
        '</div>';
      stripEl.innerHTML = histHtml;
      var onNowEl = $('s803-on-now');
      if (onNowEl && onNowEl.parentNode) onNowEl.parentNode.insertBefore(stripEl, onNowEl.nextSibling);
      var clearBtn = $('s803-hist-clear');
      if (clearBtn) clearBtn.onclick = function(){
        localStorage.removeItem('s803_watch_history');
        stripEl.remove();
      };
    }
  } catch(e){}

  // Track visits to post pages
  if (isPost) {
    try {
      var title = document.querySelector('h1.entry-title, .item-content-bottom h1');
      var thumb = document.querySelector('.temabanua-item-before img, .item-content-relative img');
      if (title) {
        var existing = JSON.parse(localStorage.getItem('s803_watch_history') || '[]');
        var entry = { title: title.textContent.trim().substring(0,60), url: location.href, thumb: thumb ? thumb.src : '', time: new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) };
        existing = existing.filter(function(e){ return e.url !== entry.url; });
        existing.unshift(entry);
        localStorage.setItem('s803_watch_history', JSON.stringify(existing.slice(0,10)));
      }
    } catch(e){}
  }
}

/* ══════════════════════════════════════════════════════════════════
   5. WATCHING NOW COUNTER (Firebase) — show on post pages
══════════════════════════════════════════════════════════════════ */
if (isPost) {
  var postKey = location.pathname.replace(/[^a-z0-9]/gi,'_').toLowerCase();
  var viewUrl = FB + '/viewers/' + postKey + '.json';

  // Increment viewer count
  getJSON(viewUrl, function(data){
    var count = ((data && data.count) || 0) + 1;
    fetch(viewUrl, { method:'PUT', body: JSON.stringify({ count: count, ts: Date.now() }) });
    // Render counter in post page
    var target = document.querySelector('.item-content-center, .item-content-bottom');
    if (target) {
      var bar = document.createElement('div');
      bar.className = 's803-watching-bar';
      bar.innerHTML = '<span class="s803-watching-dot"></span>' +
        '<span>👁 <span class="s803-watching-num" id="s803-wcount">' + (count + Math.floor(Math.random()*80)+20) + '</span> watching now</span>';
      target.appendChild(bar);
      // Simulate count updates
      setInterval(function(){
        var el = $('s803-wcount');
        if (!el) return;
        var n = parseInt(el.textContent) + (Math.random()>.5 ? 1 : -1) * Math.floor(Math.random()*3);
        el.textContent = Math.max(5, n);
      }, 8000);
    }
  }, null);
}

/* ══════════════════════════════════════════════════════════════════
   6. RELATED MATCHES WIDGET (post pages — same label)
══════════════════════════════════════════════════════════════════ */
if (isPost) {
  // Get first label from post
  var labelEl = document.querySelector('.temabanua-item-labels, .temabanua-data-meta .temabanua-item-labels');
  var labelName = labelEl ? labelEl.textContent.trim() : 'Live';
  getJSON(SITE + '/feeds/posts/default/-/' + encodeURIComponent(labelName) + '?max-results=5&orderby=published&alt=json', function(data){
    var entries = (data.feed && data.feed.entry) || [];
    var others = entries.filter(function(e){
      return !((e.link||[]).find(function(l){ return l.rel==='alternate' && l.href===location.href; }));
    }).slice(0,4);
    if (!others.length) return;
    var relEl = document.createElement('div');
    relEl.id = 's803-related-matches';
    relEl.innerHTML = '<div class="s803-widget-header">' +
      '<div class="s803-widget-title">🎬 More ' + labelName + '</div>' +
      '</div>' +
      '<div class="s803-rel-grid">' +
      others.map(function(e){
        var link = ((e.link||[]).find(function(l){ return l.rel==='alternate'; })||{}).href || '#';
        var title = (e.title && e.title.$t) || 'Match';
        var pub = e.published && e.published.$t ? new Date(e.published.$t).toLocaleDateString([],{month:'short',day:'numeric'}) : '';
        return '<a class="s803-rel-item" href="' + link + '">' +
          '<div class="s803-rel-teams">' + title + '</div>' +
          '<div class="s803-rel-meta">' + pub + '</div>' +
          '</a>';
      }).join('') + '</div>';
    var sidebar = document.querySelector('.post-sidebar, #s803-related-box');
    if (sidebar) sidebar.appendChild(relEl);
    else {
      var postBody = document.querySelector('.post-body-container, .item-content-footer');
      if (postBody && postBody.parentNode) postBody.parentNode.insertBefore(relEl, postBody.nextSibling);
    }
  }, null);
}

/* ══════════════════════════════════════════════════════════════════
   7. NOTIFICATION PERMISSION BANNER
══════════════════════════════════════════════════════════════════ */
var notifBar = $('s803-notif-bar');
var notifAllow = $('s803-notif-allow');
var notifDismiss = $('s803-notif-dismiss');
if (notifBar && 'Notification' in window && Notification.permission === 'default') {
  var notifDismissed = localStorage.getItem('s803_notif_dismissed');
  if (!notifDismissed) {
    setTimeout(function(){ notifBar.classList.add('show'); }, 5000);
    if (notifAllow) notifAllow.onclick = function(){
      Notification.requestPermission().then(function(perm){
        if (perm === 'granted') { notifBar.classList.remove('show'); localStorage.setItem('s803_notif_dismissed','1'); }
      });
    };
    if (notifDismiss) notifDismiss.onclick = function(){
      notifBar.classList.remove('show');
      localStorage.setItem('s803_notif_dismissed','1');
    };
  }
}

/* ══════════════════════════════════════════════════════════════════
   8. PWA INSTALL PROMPT
══════════════════════════════════════════════════════════════════ */
var deferredPrompt = null;
var pwaPrompt = $('s803-pwa-prompt');
var pwaInstall = $('s803-pwa-install');
var pwaLater = $('s803-pwa-later');
window.addEventListener('beforeinstallprompt', function(e){
  e.preventDefault();
  deferredPrompt = e;
  var pwaShown = localStorage.getItem('s803_pwa_shown');
  if (pwaPrompt && !pwaShown) {
    setTimeout(function(){ pwaPrompt.classList.add('show'); }, 12000);
  }
});
if (pwaInstall) pwaInstall.onclick = function(){
  if (deferredPrompt) {
    deferredPrompt.prompt();
    deferredPrompt.userChoice.then(function(){ pwaPrompt.classList.remove('show'); localStorage.setItem('s803_pwa_shown','1'); });
  }
};
if (pwaLater) pwaLater.onclick = function(){
  pwaPrompt.classList.remove('show');
  localStorage.setItem('s803_pwa_shown','1');
};

})();
