(function(){
  var FB_URL = 'https://sports-803-1b806-default-rtdb.firebaseio.com';
  var KEY_L  = 'sports803_yt_likes';
  var isPost = /\/\d{4}\/\d{2}\//.test(location.pathname);
  var isHome = /^\/?$|\/index\.html$|\?m=1/.test(location.pathname + location.search);

  /* ── 1. LIKED POSTS PANEL ── */
  (function(){
    /* Inject panel into DOM */
    var panel = document.createElement('div');
    panel.id = 's803-liked-panel';
    panel.innerHTML = '<div class="s803-panel-header">'
      + '<div class="s803-panel-title">👍 Liked Posts</div>'
      + '<button class="s803-panel-close" id="s803-liked-close">&#215;</button>'
      + '</div>'
      + '<div id="s803-liked-feed"><div style="text-align:center;padding:40px;color:rgba(255,255,255,0.3);font-size:13px;">You haven\'t liked any posts yet</div></div>';
    document.body.appendChild(panel);

    function renderLiked(){
      var feed = document.getElementById('s803-liked-feed');
      if(!feed) return;
      var liked = {};
      try { liked = JSON.parse(localStorage.getItem(KEY_L)||'{}'); } catch(e){}
      var posts = Object.values(liked);
      if(!posts.length){
        feed.innerHTML = '<div style="text-align:center;padding:40px;color:rgba(255,255,255,0.3);font-size:13px;">You haven\'t liked any posts yet</div>';
        return;
      }
      feed.innerHTML = posts.reverse().map(function(p){
        var thumb = p.thumbnail ? '<img class="s803-liked-thumb" src="'+p.thumbnail+'" loading="lazy" onerror="this.style.display=\'none\'">' : '<div class="s803-liked-thumb"></div>';
        var date = p.timestamp ? new Date(p.timestamp).toLocaleDateString([],{month:'short',day:'numeric'}) : '';
        return '<a class="s803-liked-item" href="'+p.url+'">'
          + thumb
          + '<div><div class="s803-liked-title">'+p.title+'</div><div class="s803-liked-date">'+date+'</div></div>'
          + '</a>';
      }).join('');
    }

    /* Wire up You panel "Liked Posts" menu item */
    document.addEventListener('DOMContentLoaded', function(){
      var goLiked = document.getElementById('you-go-liked');
      if(goLiked) goLiked.addEventListener('click', function(e){
        e.preventDefault();
        renderLiked();
        panel.classList.add('show');
      });
      var closeBtn = document.getElementById('s803-liked-close');
      if(closeBtn) closeBtn.addEventListener('click', function(){ panel.classList.remove('show'); });

      /* Init liked badge count */
      var liked = {};
      try { liked = JSON.parse(localStorage.getItem(KEY_L)||'{}'); } catch(e){}
      var lc = Object.keys(liked).length;
      var lb = document.getElementById('you-liked-badge');
      if(lb){ lb.textContent = lc; lb.style.display = lc ? '' : 'none'; }
    });
  })();

  /* ── 2. HOMEPAGE LTV WIDGET ── */
  window.renderLTVWidget = function(){
    var widget = document.getElementById('s803-ltv-widget');
    if(!widget) return;
    var LTV_FB = FB_URL + '/livetv/channels.json';
    fetch(LTV_FB)
      .then(function(r){return r.json();})
      .then(function(data){
        if(!data) return;
        var channels = [];
        if(typeof data==='object' && !Array.isArray(data)) Object.keys(data).forEach(function(k){channels.push(Object.assign({_key:k},data[k]));});
        else if(Array.isArray(data)) channels = data;
        if(!channels.length) return;
        widget.style.display = 'block';
        var grid = widget.querySelector('.s803-ltv-w-grid');
        if(!grid) return;
        grid.innerHTML = channels.map(function(ch){
          var logo = ch.logo
            ? '<img src="'+ch.logo+'" alt="" onerror="this.parentNode.innerHTML=\'📺\'">'
            : '📺';
          var safeUrl = ch.url.replace(/'/g,"\\'");
          var safeName = (ch.name||'').replace(/'/g,"\\'");
          return '<div class="s803-ltv-w-card" onclick="s803LTVWatch(\''+safeUrl+'\',\''+safeName+'\')">'+
            '<div class="s803-ltv-w-logo">'+logo+'</div>'+
            '<div class="s803-ltv-w-live">● LIVE</div>'+
            '<div class="s803-ltv-w-name">'+(ch.name||'Channel')+'</div>'+
            '</div>';
        }).join('');
      })
      .catch(function(){});
  };
  if(isHome) { document.addEventListener('DOMContentLoaded', renderLTVWidget); }

  /* ── 3. WATCHING NOW — above iframe on post pages ── */
  if(isPost){
    var postKey = location.pathname.replace(/[^a-z0-9]/gi,'_').toLowerCase();
    fetch(FB_URL+'/viewers/'+postKey+'.json')
      .then(function(r){return r.json();})
      .then(function(data){
        var count = ((data&&data.count)||0)+1;
        fetch(FB_URL+'/viewers/'+postKey+'.json',{method:'PUT',body:JSON.stringify({count:count,ts:Date.now()})});
        var display = count + Math.floor(Math.random()*55)+12;
        var playerWrap = document.querySelector('.item-content-relative,.item-content-image-post');
        if(!playerWrap) return;
        var bar = document.createElement('div');
        bar.className = 's803-watch-bar';
        bar.innerHTML = '<span class="s803-watch-dot"></span>👁 <span class="s803-watch-num" id="s803-wn">'+display+'</span> watching now';
        playerWrap.parentNode.insertBefore(bar, playerWrap);
        setInterval(function(){
          var el = document.getElementById('s803-wn');
          if(!el) return;
          var n = parseInt(el.textContent)+(Math.random()>.5?1:-1)*Math.floor(Math.random()*3+1);
          el.textContent = Math.max(6,n);
        },7000);
      }).catch(function(){});
  }

  /* ── 4. POST CARD VIEWER BADGES (homepage) ── */
  if(isHome){
    document.addEventListener('DOMContentLoaded', function(){
      document.querySelectorAll('.temabanua-item-before').forEach(function(card){
        if(card.querySelector('.s803-viewers-badge')) return;
        var count = Math.floor(Math.random()*650)+40;
        var badge = document.createElement('div');
        badge.className = 's803-viewers-badge';
        badge.innerHTML = '<span class="s803-vdot"></span><span class="s803-vn">'+count+'</span> watching';
        card.style.position = 'relative';
        card.appendChild(badge);
        setInterval(function(){
          count = Math.max(8, count+(Math.random()>.5?1:-1)*Math.floor(Math.random()*4+1));
          var vn = badge.querySelector('.s803-vn');
          if(vn) vn.textContent = count;
        },9000);
      });
    });
  }

})();
