(function(){
  var fallback='https://github.com/Sports803/sports803tv-mobile/releases';
  function appLink(){var value=window.S803_CFG&&window.S803_CFG.APP_LINK;return value&&/^https?:\/\//i.test(value)?value:fallback;}
  function compactPrompt(){return '<div class="s803-appgate"><div>📺</div><div class="s803-appgate__copy"><div class="s803-appgate__title">Live TV is available in the Sports803TV app</div><div class="s803-appgate__text">Install the Android app to watch live channels securely.</div></div><a class="s803-appgate__button" href="'+appLink()+'" target="_blank" rel="noopener">Install app</a></div>';}
  function openGate(){var old=document.getElementById('s803-appgate-modal');if(old)old.remove();var modal=document.createElement('div');modal.id='s803-appgate-modal';modal.className='s803-appgate-modal';modal.innerHTML='<div class="s803-appgate-modal__box" role="dialog" aria-modal="true"><div style="font-size:36px">📺</div><h2>Live TV is in the app</h2><p>Live channels can only be opened in Sports803TV for Android.</p><div class="s803-appgate-modal__actions"><button type="button" data-close="true">Not now</button><a href="'+appLink()+'" target="_blank" rel="noopener">Install Android app</a></div></div>';modal.addEventListener('click',function(e){if(e.target===modal||e.target.getAttribute('data-close'))modal.remove();});document.body.appendChild(modal);return false;}
  window.s803OpenLiveTV=openGate;window.s803LTVWatch=openGate;
  var oldNav=window.s803NavClick;window.s803NavClick=function(destination){if(String(destination||'').toLowerCase().indexOf('live')!==-1)return openGate();return typeof oldNav==='function'?oldNav.apply(this,arguments):undefined;};
  function replaceLiveWidget(){var widget=document.getElementById('s803-ltv-widget');if(widget){widget.innerHTML=compactPrompt();widget.style.display='block';}}
  function addTags(){if(document.getElementById('s803-sport-tags'))return;var target=document.querySelector('.main-wrapper,.main-container,.content-wrapper,#main-wrapper,#main');if(!target)return;var tags=[['🏎️','Motorsport','Formula 1 · F1 · MotoGP','motorsport'],['🏀','Basketball','NBA · WNBA · EuroLeague','basketball'],['🥊','Fighting','Boxing · MMA · UFC','fighting'],['⚽','Football','Soccer · Premier League · CAF','football']];var box=document.createElement('section');box.id='s803-sport-tags';box.className='s803-sport-tags';box.innerHTML='<div class="s803-sport-tags__head"><div class="s803-sport-tags__title">Browse by sport</div><div class="s803-sport-tags__note">Use these primary labels for auto-posted events</div></div><div class="s803-sport-tags__grid"></div>';var grid=box.querySelector('.s803-sport-tags__grid');tags.forEach(function(tag){var link=document.createElement('a');link.className='s803-sport-tag s803-sport-tag--'+tag[3];link.href='/search/label/'+encodeURIComponent(tag[1]);link.innerHTML=tag[0]+' '+tag[1]+'<small>'+tag[2]+'</small>';grid.appendChild(link);});target.insertBefore(box,target.firstChild);}
  function blockLinks(){document.addEventListener('click',function(e){var link=e.target.closest&&e.target.closest('a');var href=(link&&link.getAttribute('href')||'').toLowerCase();if(link&&(href.indexOf('live-tv')!==-1||href.indexOf('live%20tv')!==-1||href.indexOf('/search/label/live')!==-1)){e.preventDefault();openGate();}},true);}
  function start(){replaceLiveWidget();addTags();blockLinks();if(/live[-_ ]?tv|live-channel/i.test(location.pathname))openGate();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(start,0);});else setTimeout(start,0);
})();
